/* 自動產生：第四單元題目（id 不要改，學生的紀錄靠 id 對應） */
QBANK_ADD([
  {"id": "u4-force-01", "topic": "u4-force", "type": "single", "diff": 1, "q": "「力」看不到也摸不著。我們可以從物體的哪一種改變，知道它受到了力的作用？", "opts": ["顏色變得比較深", "發出比較濃的氣味", "形狀或運動狀態改變", "溫度變得比較低"], "ans": 2, "exp": "力雖然看不到也摸不著，但可以改變物體的形狀或運動狀態。看到物體變形，或是開始移動、停下、改變方向，就知道它受到了力。", "src": "課本 p.84"},
  {"id": "u4-force-02", "topic": "u4-force", "type": "tf", "diff": 1, "q": "力只能改變物體的形狀，不能改變物體的運動狀態。", "ans": 0, "exp": "錯。力可以改變物體的形狀，也可以改變物體的運動狀態，例如用力推停著的購物車，它就會開始移動。", "src": "課本 p.84"},
  {"id": "u4-force-03", "topic": "u4-force", "type": "single", "diff": 1, "q": "有些力必須接觸到物體才能產生作用，例如推門、拉抽屜。這類的力稱為什麼？", "opts": ["超距力", "接觸力", "重力", "磁力"], "ans": 1, "exp": "必須接觸到物體才能產生作用的力屬於接觸力，例如推力、拉力。超距力（非接觸力）不須接觸就能產生作用，例如重力、磁力。", "src": "課本 p.87"},
  {"id": "u4-force-04", "topic": "u4-force", "type": "single", "diff": 1, "q": "下列哪一種力，不須接觸到物體就可以產生作用？", "opts": ["推力", "拉力", "提起物品的力", "磁力"], "ans": 3, "exp": "磁力和重力不須接觸物體就能產生作用，屬於超距力（非接觸力）；推力、拉力、提起物品的力都必須接觸物體，屬於接觸力。", "src": "課本 p.87、108"},
  {"id": "u4-force-05", "topic": "u4-force", "type": "tf", "diff": 1, "q": "地球對物體的引力就是重力，也就是物體的重量。", "ans": 1, "exp": "對。地球上的物體都會受到地球引力的作用，地球對物體的引力叫做重力，也就是物體的重量。", "src": "課本 p.87"},
  {"id": "u4-force-06", "topic": "u4-force", "type": "tf", "diff": 1, "q": "物體受到的重力，方向是向下的。", "ans": 1, "exp": "對。重力的方向向下，是使物體往下掉落的主要原因，所以放開手中的球，球會往下掉。", "src": "課本 p.87"},
  {"id": "u4-force-07", "topic": "u4-force", "type": "single", "diff": 1, "q": "圖中的葉子沒有和任何物體接觸，卻會飄落到地面。使葉子往下掉落的主要是什麼力？", "opts": ["重力", "磁力", "推力", "拉力"], "ans": 0, "exp": "地球對物體的引力就是重力，重力是使物體向下掉落的主要原因。葉子沒有接觸任何物體，所以不是推力、拉力這類接觸力。", "src": "課本 p.87", "img": "u4/leaf-fall", "cap": "樹葉飄下來了"},
  {"id": "u4-force-08", "topic": "u4-force", "type": "single", "diff": 1, "q": "圖中的男孩用手推購物車。他推購物車的力屬於哪一類？為什麼？", "opts": ["超距力，因為力看不到也摸不著", "超距力，因為手和購物車沒有接觸", "接觸力，因為手要碰到購物車才能推", "接觸力，因為推購物車需要用很大的力"], "ans": 2, "exp": "手必須接觸購物車，才能用力推或拉它，所以推力是接觸力。力看不到也摸不著，不是分類的依據；用力大或小也不會改變力的種類。", "src": "課本 p.87", "img": "u4/cart-push", "cap": "在賣場推購物車"},
  {"id": "u4-force-09", "topic": "u4-force", "type": "tf", "diff": 1, "q": "推力和拉力都必須接觸到物體才能產生作用，屬於接觸力。", "ans": 1, "exp": "對。推力、拉力都要接觸物體才能產生作用，是接觸力；重力、磁力不須接觸，是非接觸力（超距力）。", "src": "課本 p.87、108"},
  {"id": "u4-force-10", "topic": "u4-force", "type": "single", "diff": 2, "q": "圖中的男孩用力推，原本停著的購物車就開始往前移動；他往旁邊用力推，購物車就轉彎。這說明了什麼？", "opts": ["力可以讓物體的重量變輕", "力可以改變物體的運動狀態", "推購物車的力屬於超距力", "力看得到，所以能看出購物車受力"], "ans": 1, "exp": "購物車從停著到移動、從直走到轉彎，都是運動狀態改變，表示力可以改變物體的運動狀態。推購物車的力要用手接觸，是接觸力；而且力本身看不到也摸不著。", "src": "課本 p.84、87", "img": "u4/cart-push", "cap": "在賣場推購物車"},
  {"id": "u4-force-11", "topic": "u4-force", "type": "tf", "diff": 2, "q": "圖中的葉子飄落時，沒有碰到任何物體，所以葉子沒有受到任何力的作用。", "ans": 0, "exp": "錯。葉子雖然沒有接觸任何物體，仍然受到重力的作用；重力是不須接觸就能產生作用的超距力，所以葉子會往下掉。", "src": "課本 p.87", "img": "u4/leaf-fall", "cap": "樹葉飄下來了"},
  {"id": "u4-force-12", "topic": "u4-force", "type": "single", "diff": 2, "q": "圖中的葉子沒有接觸任何物體，也會飄落到地面。下列哪一個例子中的力，和使葉子落下的力屬於同一類？", "opts": ["用手推著購物車往前走", "用力把裝滿水的水桶提起來", "拿著海綿用力刷洗髒碗盤", "磁鐵把桌上的迴紋針吸起來"], "ans": 3, "exp": "使葉子落下的重力和磁鐵吸引迴紋針的磁力，都不須接觸就能產生作用，屬於超距力（非接觸力）；推購物車、提水桶、刷洗碗盤都要用手接觸物體，是接觸力。", "src": "課本 p.87", "img": "u4/leaf-fall", "cap": "樹葉飄下來了"},
  {"id": "u4-force-13", "topic": "u4-force", "type": "single", "diff": 2, "q": "下列哪一個現象，主要是重力造成的？", "opts": ["雨滴從天空落到地面", "磁鐵把迴紋針吸起來", "用手把窗簾拉開", "用腳把球踢出去"], "ans": 0, "exp": "重力是地球對物體的引力，方向向下，是物體往下掉落的主要原因，所以雨滴會落到地面。磁鐵吸迴紋針是磁力；拉窗簾、踢球是用手腳接觸物體的接觸力。", "src": "課本 p.87"},
  {"id": "u4-force-14", "topic": "u4-force", "type": "single", "diff": 2, "q": "站上體重計就能量出人的體重。人的體重，指的是人受到哪一種力的大小？", "opts": ["磁力", "重力", "推力", "摩擦力"], "ans": 1, "exp": "地球對物體的引力就是重力，也就是物體的重量，所以體重就是人受到的重力大小。人和其他生物一樣，都會受到重力。", "src": "課本 p.86–87"},
  {"id": "u4-force-15", "topic": "u4-force", "type": "single", "diff": 2, "q": "課本把重力、磁力這類的力稱為「超距力」。「超距力」是什麼意思？", "opts": ["距離超過一公尺才會產生作用的力", "必須接觸物體才能產生作用的力", "在太空中才會產生作用的力", "不須接觸物體就能產生作用的力"], "ans": 3, "exp": "超距力也叫非接觸力，指不須接觸到物體就可以產生作用的力，例如重力、磁力；並不是距離很遠才會有作用。", "src": "課本 p.87"},
  {"id": "u4-force-16", "topic": "u4-force", "type": "tf", "diff": 1, "q": "地球上的物體，不論是人、動物等生物，或是石頭、書本等非生物，都會受到重力的作用。", "ans": 1, "exp": "對。地球上的物體（包含生物和非生物）都會受到地球引力的作用，這個引力就是重力。", "src": "課本 p.87"},
  {"id": "u4-force-17", "topic": "u4-force", "type": "single", "diff": 2, "q": "小明踢球時，用力輕或重，球滾的快慢和遠近就不同；朝左邊或右邊踢，球滾的路線也不同。這說明了力有什麼特性？", "opts": ["力有大小，也有方向", "力有大小，但是沒有方向", "力看得到，也摸得到", "踢球的力是不須接觸的超距力"], "ans": 0, "exp": "用力輕重不同、方向不同，球的運動也跟著不同，表示力有大小，也有方向。力看不到也摸不著；踢球時腳要接觸球，是接觸力。", "src": "課本 p.84"},
  {"id": "u4-force-18", "topic": "u4-force", "type": "tf", "diff": 2, "q": "接住滾過來的球，讓它停下來，這時球的運動狀態並沒有改變。", "ans": 0, "exp": "錯。球從滾動變成停下來，運動狀態改變了，這是手對球施力的結果；力可以讓物體開始移動、停下來或改變方向。", "src": "課本 p.84"},
  {"id": "u4-force-19", "topic": "u4-force", "type": "single", "diff": 2, "q": "下列哪一個例子，主要是力改變了物體的「形狀」？", "opts": ["把停著的球踢出去", "用球拍把飛來的桌球打回去", "用手把黏土捏扁", "推購物車讓它轉彎"], "ans": 2, "exp": "黏土被捏扁是形狀改變；把停著的球踢出去、把飛來的桌球打回去、讓購物車轉彎，都是力改變了物體的運動狀態（開始移動或改變方向）。", "src": "課本 p.84、86"},
  {"id": "u4-force-20", "topic": "u4-force", "type": "single", "diff": 3, "q": "小明手握著一顆球不動，球沒有往下掉。下列說明何者正確？", "opts": ["球被手握住時，就不受重力了", "手對球施的力比球的重力小", "球被握住時，重力的方向變成向上", "手對球施的力等於球的重力"], "ans": 3, "exp": "球被握住時仍然受到向下的重力；手對球施力等於球的重力，所以球才沒有往下掉。重力的方向一直是向下的，不會因為被握住而改變。", "src": "課本 p.87"},
  {"id": "u4-force-21", "topic": "u4-force", "type": "single", "diff": 3, "q": "下列四個例子中的力：①拉開抽屜的力　②磁鐵還沒碰到迴紋針，就把它吸過來的力　③使蘋果從樹上掉到地面的力　④手提起水桶的力。其中有幾個是非接觸力（超距力）？", "opts": ["1 個", "2 個", "3 個", "4 個"], "ans": 1, "exp": "②磁力和③重力不須接觸就能產生作用，是非接觸力；①拉抽屜和④提水桶都要接觸物體，是接觸力，所以共有 2 個。", "src": "課本 p.87"},
  {"id": "u4-force-22", "topic": "u4-force", "type": "single", "diff": 3, "q": "購物車停在平坦的地面上，小明用手推它往前走。這時購物車受到手的推力，也一直受到地球的重力。關於這兩個力，下列何者正確？", "opts": ["推力是接觸力，重力是非接觸力", "兩個都是接觸力，因為購物車碰著地面", "兩個都是非接觸力，因為力都看不到", "推力是非接觸力，重力是接觸力"], "ans": 0, "exp": "手必須接觸購物車才能推動它，推力是接觸力；重力是地球對物體的引力，不須接觸就能產生作用，是非接觸力（超距力），不會因為購物車碰著地面就變成接觸力。力看不到也摸不著，不是分類的依據。", "src": "課本 p.87、108"},
  {"id": "u4-force-23", "topic": "u4-force", "type": "tf", "diff": 3, "q": "一顆 3000 公克重的西瓜和一顆 200 公克重的蘋果，受到地球的重力一樣大。", "ans": 0, "exp": "錯。重力就是物體的重量，西瓜比蘋果重，受到的重力也比較大。地球上的物體都會受到重力，但重力的大小不一定相同。", "src": "課本 p.87"},
  {"id": "u4-force-24", "topic": "u4-force", "type": "single", "diff": 3, "q": "小明把球往上丟，球離開手以後，下列說法何者正確？", "opts": ["球往上飛時，手的推力還一直跟著球", "球沒接觸任何物體，所以不受任何力", "球仍然受到重力，最後會落回地面", "球往上時沒有重力，往下掉時才有"], "ans": 2, "exp": "球離開手後就像飄落的葉子，沒有接觸任何物體；手的推力是接觸力，球離開手就不再受到它。但重力不須接觸，一直作用在球上，所以球最後會落回地面。", "src": "課本 p.87"},
  {"id": "u4-spring-01", "topic": "u4-spring", "type": "single", "diff": 1, "q": "小美這一組選擇用彈簧來測量力的大小。下列哪一個是課本說的理由？", "opts": ["受力大小不同，伸長的長度也不同", "受力愈大，彈簧伸長的長度愈短", "不受力時，彈簧會保持拉長的樣子", "彈簧只能用壓的方式改變形狀"], "ans": 0, "exp": "課本說：彈簧受力大小不同時，伸長的長度也不同；不受力時通常又會恢復原來的長度。受力愈大，彈簧伸長得愈長；小美這一組的彈簧可以用拉或壓的方式改變形狀。", "src": "課本 p.88"},
  {"id": "u4-spring-02", "topic": "u4-spring", "type": "tf", "diff": 1, "q": "有彈性的物體所能承受的最大作用力數值，稱作「彈性限度」。", "ans": 1, "exp": "對。彈簧在一定的範圍內受力，外力移除後還能恢復原狀；它所能承受的最大作用力數值，就叫做彈性限度。", "src": "課本 p.88"},
  {"id": "u4-spring-03", "topic": "u4-spring", "type": "tf", "diff": 1, "q": "彈簧受力超過彈性限度後，只要把外力移除，彈簧還是會恢復原狀。", "ans": 0, "exp": "錯。在彈性限度內，外力移除後彈簧才能恢復原狀；一旦受力超過彈性限度，彈簧便無法恢復原狀了。", "src": "課本 p.88"},
  {"id": "u4-spring-04", "topic": "u4-spring", "type": "single", "diff": 1, "q": "課本中有一組同學想用「壓皮球」的方式來測量力的大小。大家討論後，發現用皮球有什麼問題？", "opts": ["皮球充氣的程度會影響變形程度", "皮球的顏色會影響變形程度", "皮球被壓時形狀不會改變", "皮球只能用拉的方式看到變形"], "ans": 0, "exp": "壓皮球會讓它變形，但皮球充氣的程度會影響變形程度，所以比較不適合用來測量力的大小。皮球是用壓的方式觀察變形；只能用拉的方式看到變形的是橡皮筋。", "src": "課本 p.88"},
  {"id": "u4-spring-05", "topic": "u4-spring", "type": "single", "diff": 1, "q": "用手往下拉彈簧時，彈簧會變長，但很難知道手用了多少力。課本想到可以用什麼方法來表示拉彈簧的力有多大？", "opts": ["在彈簧下面掛物體，用物體的重量表示", "請力氣比較大的同學來拉彈簧", "用兩隻手一起往下拉彈簧", "數一數用手拉了幾秒鐘"], "ans": 0, "exp": "課本的想法是在彈簧下面掛物體，用物體的重量來代表拉彈簧的力。換人拉、用兩隻手拉、數拉了幾秒，都還是不知道用了多少力。", "src": "課本 p.89"},
  {"id": "u4-spring-06", "topic": "u4-spring", "type": "single", "diff": 1, "q": "想在彈簧下面掛物體來代表力的大小。小英這一組選用砝碼，而不用橡皮擦或鉛筆，主要是因為砝碼有什麼特點？", "opts": ["大小相同、重量固定", "顏色鮮豔、容易看見", "每個人都有、容易收集", "形狀細長、方便綁線"], "ans": 0, "exp": "砝碼的材料大小相同而且重量固定，掛上的數量多寡就能表示用力的大小。大家的橡皮擦、鉛筆大小和重量都不一樣，不適合用來代表力的大小。", "src": "課本 p.89–90"},
  {"id": "u4-spring-07", "topic": "u4-spring", "type": "tf", "diff": 1, "q": "用大小相同、重量固定的砝碼做實驗時，掛上的砝碼數量愈多，表示彈簧受到的拉力愈大。", "ans": 1, "exp": "對。每個砝碼都一樣重，所以砝碼數量的多寡可以用來表示用力的大小；數量愈多，彈簧受到的拉力愈大。", "src": "課本 p.90"},
  {"id": "u4-spring-08", "topic": "u4-spring", "type": "single", "diff": 1, "q": "照片中的彈簧掛著課本實驗用的砝碼。這些砝碼的總重量是多少？", "opts": ["2 公克重", "10 公克重", "20 公克重", "200 公克重"], "ans": 2, "exp": "課本實驗用的砝碼一個是 10 公克重，照片中掛了 2 個，所以總重量是 20 公克重。", "src": "課本 p.90", "img": "u4/spring-2", "cap": "彈簧下面掛著實驗用的砝碼"},
  {"id": "u4-spring-09", "topic": "u4-spring", "type": "single", "diff": 1, "q": "照片中，直尺和彈簧已經固定在支架上，還沒有掛砝碼。開始掛砝碼之前，應該先做什麼？", "opts": ["量出彈簧原來的長度", "用力把彈簧拉長一次", "先掛最重的物品試試看", "把尺拿走以免擋住彈簧"], "ans": 0, "exp": "實驗的第一步是把尺和彈簧固定在支架上，並量出彈簧原來的長度；有了原來的長度，掛砝碼後才能算出伸長量。先用力拉或掛很重的物品，可能讓彈簧超過彈性限度。", "src": "課本 p.90", "img": "u4/spring-0", "cap": "支架上固定了直尺和彈簧"},
  {"id": "u4-spring-10", "topic": "u4-spring", "type": "tf", "diff": 1, "q": "做照片中的實驗時，每次測量完後，要把砝碼取下，檢查彈簧能不能恢復原來的長度。", "ans": 1, "exp": "對。課本提醒每次測量完都要取下砝碼，檢查彈簧能不能恢復原來的長度；能恢復，表示彈簧還在彈性限度內。", "src": "課本 p.90", "img": "u4/spring-2", "cap": "彈簧掛著砝碼"},
  {"id": "u4-spring-11", "topic": "u4-spring", "type": "single", "diff": 1, "q": "彈簧的「伸長量」要怎麼算出來？", "opts": ["掛砝碼後的總長度－原來的長度", "掛砝碼後的總長度＋原來的長度", "砝碼的重量÷彈簧原來的長度", "掛砝碼後的總長度就是伸長量"], "ans": 0, "exp": "伸長量是彈簧比原來多出來的長度，要用掛砝碼後的總長度減去原來的長度。例如原來 4.5 公分、掛 2 個砝碼後總長度 5.4 公分，伸長量是 0.9 公分。", "src": "課本 p.90–91"},
  {"id": "u4-spring-12", "topic": "u4-spring", "type": "single", "diff": 1, "q": "〈科學閱讀〉介紹的虎克在牛津大學當工友時，因為偶然的機會，成為哪一位化學家的助教？", "opts": ["波以耳", "牛頓", "愛迪生", "伽利略"], "ans": 0, "exp": "虎克在牛津大學當工友，偶然成為化學家波以耳的助教，還發明了第一部真空抽氣機。波以耳也是第三單元〈石蕊試紙的發明〉提到的科學家。", "src": "課本 p.106"},
  {"id": "u4-spring-13", "topic": "u4-spring", "type": "single", "diff": 2, "q": "小華這一組想用橡皮筋測量力的大小。根據課本的討論，橡皮筋比較不適合的原因可能是什麼？", "opts": ["拉久了可能無法恢復原狀", "橡皮筋受力時完全不會變形", "橡皮筋被拉時長度會變短", "橡皮筋只能用壓的方式測量"], "ans": 0, "exp": "橡皮筋只能用拉的方式看到變形，而且拉的時間長了可能無法恢復原狀。彈簧是金屬材質，停止受力後通常會恢復原狀，比較適合用來測量力的大小。", "src": "課本 p.88"},
  {"id": "u4-spring-14", "topic": "u4-spring", "type": "single", "diff": 2, "q": "三條相同的彈簧，原來都長 4.5 公分，分別掛上不同數量的砝碼（每個 10 公克重），總長度如圖。哪一條彈簧的伸長量是 3.1 公分？", "opts": ["甲", "乙", "丙"], "ans": 1, "exp": "伸長量＝總長度－原來長度。乙是 7.6－4.5＝3.1 公分；甲是 6.5－4.5＝2.0 公分，丙是 5.4－4.5＝0.9 公分。圖上寫的是總長度，要減去原來的長度才是伸長量。", "src": "課本 p.91", "cap": "同一條彈簧掛上不同數量的砝碼", "fig": {"type": "spring", "show": true, "items": [{"lab": "甲", "n": 3, "len": 6.5}, {"lab": "乙", "n": 4, "len": 7.6}, {"lab": "丙", "n": 2, "len": 5.4}]}},
  {"id": "u4-spring-15", "topic": "u4-spring", "type": "single", "diff": 2, "q": "圖中彈簧的上端對齊直尺的 0，掛了 2 個砝碼後，虛線對到的位置是 5.4 公分。這個 5.4 公分代表什麼？", "opts": ["彈簧現在的總長度", "彈簧多伸長出來的長度", "兩個砝碼的總重量", "彈簧原來的長度"], "ans": 0, "exp": "彈簧上端對齊 0、下端對到 5.4 公分，所以 5.4 公分是掛砝碼後的總長度。伸長量要再減去原來的長度：5.4－4.5＝0.9 公分。", "src": "課本 p.90", "fig": {"type": "spring", "show": true, "items": [{"n": 2, "len": 5.4}]}},
  {"id": "u4-spring-16", "topic": "u4-spring", "type": "single", "diff": 2, "q": "小明的紀錄（彈簧原來長 4.5 公分）：砝碼 0、10、20、30、40、50 公克重時，彈簧總長度依序是 4.5、4.6、5.4、6.5、7.6、8.7 公分。當彈簧的長度呈現有規律變化後，每多掛一個 10 公克重的砝碼，彈簧會再伸長多少？", "opts": ["0.1 公分", "1.1 公分", "0.9 公分", "4.5 公分"], "ans": 1, "exp": "從 20 公克重開始，總長度 5.4→6.5→7.6→8.7 公分，每多 10 公克重就多伸長 1.1 公分。第一個 10 公克重只伸長 0.1 公分，那時長度還沒有呈現這個規律。", "src": "課本 p.91"},
  {"id": "u4-spring-17", "topic": "u4-spring", "type": "tf", "diff": 2, "q": "小明的紀錄：砝碼 0、10、20、30、40、50 公克重時，彈簧伸長量依序是 0、0.1、0.9、2.0、3.1、4.2 公分。根據這份紀錄，從掛上第 1 個砝碼開始，每多掛 1 個砝碼，彈簧都會多伸長 1.1 公分。", "ans": 0, "exp": "錯。掛第 1 個砝碼只伸長 0.1 公分，第 2 個多伸長 0.8 公分；要等彈簧的長度呈現有規律變化後（20 公克重以後），每多 10 公克重才多伸長 1.1 公分。", "src": "課本 p.91"},
  {"id": "u4-spring-18", "topic": "u4-spring", "type": "single", "diff": 2, "q": "這是小明把實驗紀錄畫成的座標圖。根據座標圖，彈簧伸長量是 3.1 公分時，掛的砝碼重量是多少？", "opts": ["40 公克重", "30 公克重", "31 公克重", "50 公克重"], "ans": 0, "exp": "在圖上找到伸長量 3.1 公分的點，往下對到橫軸是 40 公克重，也就是 4 個 10 公克重的砝碼。", "src": "課本 p.91", "fig": {"type": "chart", "chart": {"type": "line", "xLabel": "砝碼重量（公克重）", "yLabel": "伸長量（公分）", "x": ["0", "10", "20", "30", "40", "50"], "series": [{"name": "伸長量", "data": [0, 0.1, 0.9, 2.0, 3.1, 4.2]}]}}},
  {"id": "u4-spring-19", "topic": "u4-spring", "type": "single", "diff": 2, "q": "這是小明把實驗紀錄畫成的座標圖。從圖中可以知道彈簧的伸長量和砝碼的重量有什麼關係？", "opts": ["彈性限度內，砝碼愈重伸長量愈長", "砝碼愈重，彈簧的伸長量反而愈短", "伸長量不會隨著砝碼重量而改變", "砝碼愈重，彈簧原來的長度就愈長"], "ans": 0, "exp": "座標圖的線一路往上，表示在彈性限度內，砝碼的重量愈重，彈簧的伸長量愈長。彈簧原來的長度是不掛砝碼時量的，不會因為掛砝碼而改變。", "src": "課本 p.91", "fig": {"type": "chart", "chart": {"type": "line", "xLabel": "砝碼重量（公克重）", "yLabel": "伸長量（公分）", "x": ["0", "10", "20", "30", "40", "50"], "series": [{"name": "伸長量", "data": [0, 0.1, 0.9, 2.0, 3.1, 4.2]}]}}},
  {"id": "u4-spring-20", "topic": "u4-spring", "type": "single", "diff": 2, "q": "要把小明的紀錄畫成座標圖，橫軸是砝碼重量、縱軸是彈簧伸長量。掛 30 公克重時，彈簧總長度 6.5 公分、伸長量 2.0 公分。畫這一點時應該怎麼做？", "opts": ["在橫軸找到 30，再往上對到 2.0", "在橫軸找到 30，再往上對到 6.5", "在縱軸找到 30，再往右對到 2.0", "在橫軸找到 2.0，再往上對到 30"], "ans": 0, "exp": "先在橫軸找到砝碼重量 30 公克重，再往上對到伸長量 2.0 公分，就是那個點。縱軸是伸長量，不是總長度，所以不能對到 6.5。", "src": "課本 p.91"},
  {"id": "u4-spring-21", "topic": "u4-spring", "type": "tf", "diff": 2, "q": "把大家的橡皮擦集合起來掛在彈簧下面，橡皮擦的數量多寡，就能準確表示用力的大小。", "ans": 0, "exp": "錯。大家的橡皮擦大小和重量都不一樣，數量相同時重量不一定相同；要用大小相同、重量固定的砝碼，數量多寡才能表示用力的大小。", "src": "課本 p.89–90"},
  {"id": "u4-spring-22", "topic": "u4-spring", "type": "single", "diff": 2, "q": "小明想一直增加彈簧下方的砝碼，看看彈簧最多能伸多長。這樣做為什麼不恰當？", "opts": ["可能超過彈性限度而無法恢復原狀", "砝碼愈多，彈簧的伸長量反而變少", "掛愈多砝碼，彈簧原來的長度會變短", "砝碼掛愈多，每個砝碼就會變得愈輕"], "ans": 0, "exp": "砝碼的重量不能毫無限制的增加。受力超過彈性限度，彈簧便無法恢復原狀，所以不可以掛過重的物品。", "src": "課本 p.88、91"},
  {"id": "u4-spring-23", "topic": "u4-spring", "type": "single", "diff": 2, "q": "甲、乙是兩條不同的彈簧，原來長度都是 4.5 公分，各掛上 2 個相同的砝碼後如圖。下列說法何者正確？", "opts": ["甲的伸長量比乙長", "乙的伸長量比甲長", "兩條彈簧的伸長量一樣", "甲受到的拉力比乙大"], "ans": 0, "exp": "兩條彈簧掛的砝碼一樣，受到的拉力相同；甲伸長 7－4.5＝2.5 公分，乙伸長 5.4－4.5＝0.9 公分。不同彈簧的彈性不同，受相同的力，伸長量也可能不同。", "src": "課本 p.91", "cap": "兩條不同的彈簧各掛上 2 個砝碼", "fig": {"type": "spring", "show": true, "items": [{"lab": "甲", "n": 2, "len": 7.0}, {"lab": "乙", "n": 2, "len": 5.4}]}},
  {"id": "u4-spring-24", "topic": "u4-spring", "type": "tf", "diff": 2, "q": "〈科學閱讀：虎克〉提到：在彈性限度內，材料所受的力與材料的變形量成正比。", "ans": 1, "exp": "對。這就是「虎克定律」；但是力量超過材料的彈性限度時，就不會遵守虎克定律了。", "src": "課本 p.106–107"},
  {"id": "u4-spring-25", "topic": "u4-spring", "type": "single", "diff": 3, "q": "小明的紀錄（彈簧原來長 4.5 公分）：砝碼 0、10、20、30、40、50 公克重時，彈簧伸長量依序是 0、0.1、0.9、2.0、3.1、4.2 公分。他在同一條彈簧下掛一個小袋子（沒有超過彈性限度），量得彈簧的總長度是 6.5 公分。小袋子大約多重？", "opts": ["30 公克重", "70 公克重", "20 公克重", "65 公克重"], "ans": 0, "exp": "總長度 6.5 公分，伸長量是 6.5－4.5＝2.0 公分；紀錄中伸長 2.0 公分時掛的是 30 公克重，所以小袋子大約 30 公克重。如果把 6.5 公分當成伸長量，就會錯估成 70 公克重左右。", "src": "課本 p.91"},
  {"id": "u4-spring-26", "topic": "u4-spring", "type": "single", "diff": 3, "q": "小明的紀錄（彈簧原來長 4.5 公分）：砝碼 0、10、20、30、40、50 公克重時，彈簧總長度依序是 4.5、4.6、5.4、6.5、7.6、8.7 公分。如果掛到 60 公克重時仍在彈性限度內，而且繼續保持同樣的規律，彈簧的總長度應該是多少？", "opts": ["9.8 公分", "5.3 公分", "8.8 公分", "10.9 公分"], "ans": 0, "exp": "長度呈現規律後，每多 10 公克重多伸長 1.1 公分，所以 60 公克重時總長度是 8.7＋1.1＝9.8 公分。5.3 公分是這時的伸長量（9.8－4.5），不是總長度。", "src": "課本 p.91"},
  {"id": "u4-spring-27", "topic": "u4-spring", "type": "tf", "diff": 3, "q": "甲彈簧原來長 4 公分，乙彈簧原來長 6 公分，各掛上 2 個相同的砝碼後，甲的總長度是 7 公分，乙的總長度是 8 公分。因為乙的總長度比較長，所以乙的伸長量比較長。", "ans": 0, "exp": "錯。伸長量＝總長度－原來長度：甲伸長 7－4＝3 公分，乙伸長 8－6＝2 公分，所以是甲的伸長量比較長。兩條彈簧原來的長度不同時，不能只比較總長度。", "src": "課本 p.90–91"},
  {"id": "u4-spring-28", "topic": "u4-spring", "type": "single", "diff": 3, "q": "小安掛上砝碼測量後，把砝碼全部取下，發現彈簧長度變成 5.0 公分，回不到原來的 4.5 公分。最可能的原因是什麼？", "opts": ["受力超過了彈簧的彈性限度", "掛的砝碼太輕，彈簧還沒伸長", "取下砝碼後，彈簧變得更有彈性", "直尺被砝碼拉長了一點"], "ans": 0, "exp": "在彈性限度內，取下砝碼後彈簧能恢復原來的長度；回不到原來的長度，表示受力可能已經超過彈性限度。所以每次測量完都要取下砝碼檢查。", "src": "課本 p.88、90"},
  {"id": "u4-spring-29", "topic": "u4-spring", "type": "single", "diff": 3, "q": "在一條彈簧下面一個一個掛上相同的罐頭，伸長量如圖。根據〈虎克〉閱讀中虎克定律的說明，下列推論何者最合理？", "opts": ["掛第 4 個罐頭時，可能已超過彈性限度", "掛 1～3 個罐頭時，就已超過彈性限度", "罐頭掛得愈多，彈簧伸長量愈短", "伸長量和罐頭數量完全沒有規律"], "ans": 0, "exp": "掛 1～3 個罐頭時，每多一個都多伸長 0.6 公分，有一定的規律；第 4 個卻多伸長 1.2 公分，不再遵守原本的規律，可能已經超過彈性限度，這時就不遵守虎克定律了。", "src": "課本 p.106–107", "fig": {"type": "chart", "chart": {"type": "line", "xLabel": "罐頭數量（個）", "yLabel": "伸長量（公分）", "x": ["0", "1", "2", "3", "4"], "series": [{"name": "伸長量", "data": [0, 0.6, 1.2, 1.8, 3.0]}]}}},
  {"id": "u4-spring-30", "topic": "u4-spring", "type": "single", "diff": 3, "q": "小凱和小明用不同的彈簧、相同的砝碼做實驗。小凱的彈簧掛 30 公克重後，取下砝碼就回不到原來的長度；小明的彈簧掛 50 公克重後，取下砝碼還能恢復原來的長度。下列推論何者正確？", "opts": ["小凱的彈簧彈性限度比較小", "兩條彈簧的彈性限度一定相同", "小明的彈簧已經超過彈性限度", "回不到原長和掛的重量無關"], "ans": 0, "exp": "小凱的彈簧掛 30 公克重就無法恢復原狀，表示已經超過它的彈性限度；小明的彈簧掛 50 公克重還能恢復，表示還在彈性限度內。不同彈簧的彈性不同，能承受的最大作用力也不相同。", "src": "課本 p.88、91"},
  {"id": "u4-scale-01", "topic": "u4-scale", "type": "single", "diff": 1, "q": "彈簧秤是利用彈簧的什麼特性做成的測量工具？", "opts": ["受熱時會伸長，遇冷時會縮短", "受力後形狀會改變，不受力時會恢復原狀", "受力後形狀不會改變，所以很堅固", "受力後被拉長，而且會一直維持拉長的樣子"], "ans": 1, "exp": "彈簧秤是利用彈簧受力後形狀會改變、不受力時會恢復原狀的原理做成的。如果彈簧拉長後一直不能恢復原狀，就沒辦法重複測量了。", "src": "課本 p.92"},
  {"id": "u4-scale-02", "topic": "u4-scale", "type": "tf", "diff": 1, "q": "彈簧秤受力時指針會移動，指針最後停住不動的刻度讀數，就代表當時用力的大小。", "ans": 1, "exp": "對。指針還在移動時不要急著讀，要等指針最後停住不動，那個刻度讀數就是當時用力的大小。", "src": "課本 p.92"},
  {"id": "u4-scale-03", "topic": "u4-scale", "type": "single", "diff": 1, "q": "使用彈簧秤測量之前，第一件要做的事是什麼？", "opts": ["先歸零，讓指針對準 0", "先掛上最重的砝碼試試看", "先把彈簧秤上下倒過來", "先用力把掛鉤拉到最下面"], "ans": 0, "exp": "測量之前要先將彈簧秤歸零，沒有受力時指針對準 0，讀到的數字才正確。用力拉到最下面或掛太重的東西，可能超過彈簧的彈性限度；上下倒過來則無法歸零。", "src": "課本 p.92"},
  {"id": "u4-scale-04", "topic": "u4-scale", "type": "single", "diff": 2, "q": "照片中的彈簧秤上下倒過來掛，下面沒有掛任何東西。課本說彈簧秤不可以這樣使用，原因是什麼？", "opts": ["倒過來掛時，彈簧受力不會伸長", "沒掛東西時指針不在 0，無法歸零", "倒過來掛時，指針會停在最大刻度 250", "倒過來掛時，彈簧會被壓壞而不能用"], "ans": 1, "exp": "彈簧秤的上端和下端不可以倒過來使用：照片中沒有掛東西，指針卻沒有停在 0，無法歸零，量出來的讀數就不正確。從放大圈也看得到指針不在 250。", "src": "課本 p.92", "img": "u4/scale-upside", "cap": "右邊圓圈是指針附近放大的樣子"},
  {"id": "u4-scale-05", "topic": "u4-scale", "type": "single", "diff": 1, "q": "讀彈簧秤的刻度時，眼睛應該放在圖中哪一個位置？", "opts": ["甲", "乙", "丙"], "ans": 2, "exp": "眼睛要和指針同在一水平面上，看到的讀數才會正確；丙和指針一樣高。乙比指針高、甲比指針低，斜著看都會讀不準。", "src": "課本 p.92", "fig": {"type": "springscale", "val": 100, "eyes": true, "lab": ["乙", "丙", "甲"]}},
  {"id": "u4-scale-06", "topic": "u4-scale", "type": "single", "diff": 1, "q": "彈簧秤的構造中，用來懸掛要測量的物品，也可以用手輕拉的是哪一個部分？", "opts": ["吊環", "指針", "掛鉤", "刻度"], "ans": 2, "exp": "掛鉤在彈簧秤的下端，用來懸掛物品或用手輕拉；吊環在上端，是用來吊掛彈簧秤的。", "src": "課本 p.93"},
  {"id": "u4-scale-07", "topic": "u4-scale", "type": "tf", "diff": 1, "q": "把物品掛在已經歸零的彈簧秤下，指針往下移得愈多，表示這個物品愈輕。", "ans": 0, "exp": "錯。課本的彈簧秤 0 在最上面，愈往下數字愈大；指針往下移得愈多，表示彈簧被拉得愈長、受的力愈大，物品愈重。", "src": "課本 p.92–93"},
  {"id": "u4-scale-08", "topic": "u4-scale", "type": "single", "diff": 1, "q": "小華用手往下拉彈簧秤的掛鉤，指針停住不動時的位置如照片。小華拉的力是多少？", "opts": ["100 公克重", "150 公克重", "200 公克重", "250 公克重"], "ans": 1, "exp": "指針最後停在 150 的刻度上，表示手往下拉的力是 150 公克重。彈簧秤上寫的 250g 是它的最大刻度，不是這次的讀數。", "src": "課本 p.92", "img": "u4/scale-pull", "cap": "右邊圓圈是指針附近放大的樣子"},
  {"id": "u4-scale-09", "topic": "u4-scale", "type": "single", "diff": 2, "q": "把一個物品掛在已經歸零的彈簧秤下，指針停住不動時的位置如圖。這個物品的重量是多少？", "opts": ["150 公克重", "160 公克重", "170 公克重", "180 公克重"], "ans": 2, "exp": "每 50 公克重之間分成 5 小格，每一小格是 10 公克重；指針在 150 再往下 2 小格，所以是 170 公克重。只看最近的數字會誤讀成 150，數錯小格會讀成 160 或 180。", "src": "課本 p.92", "fig": {"type": "springscale", "val": 170, "load": "weight"}},
  {"id": "u4-scale-10", "topic": "u4-scale", "type": "single", "diff": 3, "q": "這支彈簧秤的最大刻度是 500 公克重。把一個物品掛上去，指針停住不動時的位置如圖。讀數是多少？", "opts": ["230 公克重", "240 公克重", "260 公克重", "300 公克重"], "ans": 2, "exp": "這支彈簧秤每 100 公克重之間分成 5 小格，每一小格是 20 公克重；指針在 200 再往下 3 小格，所以是 260 公克重。如果把一小格當成 10 公克重，就會誤讀成 230。", "src": "課本 p.92", "fig": {"type": "springscale", "max": 500, "step": 100, "minor": 20, "val": 260, "load": "weight"}},
  {"id": "u4-scale-11", "topic": "u4-scale", "type": "tf", "diff": 2, "q": "彈簧秤刻度上的數字，表示裡面的彈簧被拉長了幾公分。", "ans": 0, "exp": "錯。彈簧秤的刻度讀數表示測量物的重量（用力的大小），單位是公克重，不是彈簧伸長的公分數。", "src": "課本 p.92–93"},
  {"id": "u4-scale-12", "topic": "u4-scale", "type": "tf", "diff": 2, "q": "彈簧秤只能秤掛在下面的物品有多重，不能用來測量手拉的力有多大。", "ans": 0, "exp": "錯。掛鉤可以懸掛物品，也可以用手輕拉；用手往下拉時，指針最後停住的讀數就是手用力的大小。", "src": "課本 p.92–93"},
  {"id": "u4-scale-13", "topic": "u4-scale", "type": "single", "diff": 2, "q": "照片是兩支相同的彈簧秤打開後，裡面彈簧的樣子；其中一支下面掛了砝碼，另一支沒有掛。下列判斷方法和理由，哪一個正確？", "opts": ["彈簧比較長的那支有掛，因為彈簧受力會被拉長", "彈簧比較短的那支有掛，因為砝碼會把彈簧壓短", "彈簧顏色比較深的那支有掛，因為受力會變色", "兩支一樣長，因為彈簧受力後長度不會改變"], "ans": 0, "exp": "掛在彈簧秤下的砝碼是把彈簧往下拉，彈簧受力會被拉長，所以彈簧比較長、圈圈分開的那支掛了砝碼；沒有掛的彈簧比較短，圈圈擠在一起。彈簧秤就是利用這種長度的變化來測量力的大小。", "src": "課本 p.93", "img": "u4/scale-inside", "cap": "兩支彈簧秤裡面的彈簧"},
  {"id": "u4-scale-14", "topic": "u4-scale", "type": "tf", "diff": 1, "q": "照片是一種磅秤拆開後的內部。這種磅秤和彈簧秤一樣，是利用彈簧受力後長度會改變的原理來秤重。", "ans": 1, "exp": "對。照片中的磅秤裡面有彈簧，物品放上去時彈簧受力、長度改變，再帶動指針轉動顯示重量。課本中的體重計也是利用彈簧受力後長度改變的原理。", "src": "課本 p.93", "img": "u4/kitchen-scale-inside"},
  {"id": "u4-scale-15", "topic": "u4-scale", "type": "single", "diff": 2, "q": "下列哪一種物品裡雖然有彈簧，卻不是用來測量重量或力的工具？", "opts": ["體重計", "磅秤", "彈簧秤", "摩托車的避震器"], "ans": 3, "exp": "摩托車避震器和一些遊樂器材裡雖然有彈簧，但它們不是測量工具；課本中的體重計、磅秤和彈簧秤，都是利用彈簧受力後長度改變來測量重量或力。", "src": "課本 p.93"},
  {"id": "u4-scale-16", "topic": "u4-scale", "type": "single", "diff": 2, "q": "小明用手往下拉已經歸零的彈簧秤，指針停住時讀數是 150 公克重；小華在同一支彈簧秤下面掛一個水壺，指針停住時讀數也是 150 公克重。下列說法哪一個正確？", "opts": ["小明拉的力和水壺的重量一樣大", "小明拉的力比較大，因為手有用力", "水壺的重量比較大，因為它受到重力", "手拉的力和重量不同，不能比較大小"], "ans": 0, "exp": "彈簧秤可以測量手拉的力，也可以測量物品的重量（重力），單位都是公克重。同一支彈簧秤讀數都是 150 公克重，表示小明拉的力和水壺的重量一樣大。", "src": "課本 p.87、92"},
  {"id": "u4-scale-17", "topic": "u4-scale", "type": "single", "diff": 2, "q": "小明想用一條彈簧，自己做一個能測量力的工具。除了彈簧和掛鉤，還一定要加上什麼，才能方便讀出力的大小？", "opts": ["把彈簧換成橡皮筋", "在彈簧上塗潤滑油", "指針和刻度", "把彈簧剪成兩段"], "ans": 2, "exp": "彈簧要成為測量工具，需要把伸長的長度轉成刻度，才方便讀取；彈簧秤就是用指針指在刻度上讀出用力的大小。橡皮筋受力久了可能無法恢復原狀，不適合。", "src": "課本 p.88、93"},
  {"id": "u4-scale-18", "topic": "u4-scale", "type": "single", "diff": 3, "q": "小明把一袋東西掛在最大刻度 250 公克重的彈簧秤上，指針一下子就被拉到最下面 250 的地方。下列哪一種做法最恰當？", "opts": ["記錄這袋東西剛好是 250 公克重", "再用手往下拉，看指針還能到哪裡", "把彈簧秤倒過來掛，再測一次", "馬上取下，改用能秤更重物品的工具"], "ans": 3, "exp": "指針已經到最大刻度，這袋東西可能超過 250 公克重，讀不出真正的重量；繼續掛著或再用力拉，可能超過彈簧的彈性限度，使彈簧無法恢復原狀。應該取下，改用磅秤等能秤更重物品的工具。", "src": "課本 p.88、92"},
  {"id": "u4-scale-19", "topic": "u4-scale", "type": "tf", "diff": 3, "q": "一支彈簧秤沒有掛東西時，指針停在 20 的位置（沒有歸零）。直接拿它去秤鉛筆盒，讀到的數字會比鉛筆盒真正的重量大。", "ans": 1, "exp": "對。沒掛東西時指針就已經在 20，掛上鉛筆盒後指針會從 20 再往下移，讀數會比真正的重量多。所以測量前一定要先歸零。", "src": "課本 p.92"},
  {"id": "u4-scale-20", "topic": "u4-scale", "type": "single", "diff": 3, "q": "把一顆蘋果掛在已經歸零的彈簧秤下，指針停在 200 的位置。把蘋果拿下來後，指針會怎樣？原因是什麼？", "opts": ["通常會回到 0，因為彈簧不受力時會恢復原狀", "通常會回到 0，因為蘋果拿下來後就沒有重力了", "會停在 200，因為彈簧已經被拉長了", "會停在 100，因為彈簧只會恢復一半"], "ans": 0, "exp": "彈簧秤是利用彈簧受力後形狀改變、不受力時恢復原狀的原理；蘋果拿下來後彈簧不再被拉，通常會恢復原長，指針回到 0。蘋果還是有重力（重量約 200 公克重），只是不再拉彈簧秤了。", "src": "課本 p.87、92"},
  {"id": "u4-balance-01", "topic": "u4-balance", "type": "single", "diff": 1, "q": "照片中的拔河繩上綁著一條紅布條。比賽時，觀察紅布條的移動，可以知道什麼？", "opts": ["哪一隊用的力量比較大", "哪一隊的人數比較多", "兩隊各用了多少公克重的力", "哪一隊隊員的體重比較重"], "ans": 0, "exp": "紅布條會往用力大的一方移動，所以看紅布條往哪一隊移動，就知道哪一隊用的力量比較大；紅布條不動，表示兩隊用力相同。紅布條看不出兩隊各用了多少公克重的力，也看不出人數或體重。", "src": "課本 p.94", "img": "u4/tug", "cap": "拔河比賽"},
  {"id": "u4-balance-02", "topic": "u4-balance", "type": "single", "diff": 1, "q": "照片中兩隊正在拔河。兩隊對繩子用力的方向是怎樣？", "opts": ["兩隊拉的方向相反", "兩隊拉的方向相同", "只有力量大的那隊在拉", "兩隊都往紅布條那邊拉"], "ans": 0, "exp": "兩隊都把繩子往自己那邊拉（離開紅布條的方向），所以繩子兩邊都受到力，兩個力的方向相反。兩隊都在出力，只是力量大小可能不同。", "src": "課本 p.94", "img": "u4/tug", "cap": "拔河比賽"},
  {"id": "u4-balance-03", "topic": "u4-balance", "type": "tf", "diff": 1, "q": "甲、乙兩隊拔河，繩子上的紅布條往乙隊移動，表示乙隊用的力量比較大。", "ans": 1, "exp": "對。紅布條會往用力大的一方移動，往乙隊移動就表示乙隊用的力量比甲隊大。", "src": "課本 p.94、108"},
  {"id": "u4-balance-04", "topic": "u4-balance", "type": "single", "diff": 1, "q": "進行拔河比賽時，下列哪一個做法比較安全？", "opts": ["選擇空曠的場地進行", "快要輸時突然鬆開繩子", "在桌椅很多的教室裡比賽", "在樓梯旁邊比賽"], "ans": 0, "exp": "拔河要選擇空曠的場地，旁邊沒有桌椅、樓梯等容易撞到或跌落的地方；拔河時也不可以突然鬆手，以免發生意外。", "src": "課本 p.94"},
  {"id": "u4-balance-05", "topic": "u4-balance", "type": "single", "diff": 1, "q": "模擬拔河的實驗中，迴紋針兩端要用什麼工具鉤住來拉，才能知道每一邊拉力的大小？", "opts": ["彈簧秤", "橡皮筋", "長尾夾", "直尺"], "ans": 0, "exp": "彈簧秤上有刻度，指針停住的讀數就是拉力的大小；用兩個彈簧秤鉤住迴紋針兩端，就能知道兩邊各用了多少力。", "src": "課本 p.95"},
  {"id": "u4-balance-06", "topic": "u4-balance", "type": "single", "diff": 1, "q": "甲、乙兩方用彈簧秤拉迴紋針，拉力如圖。鬆開壓住迴紋針的手後，迴紋針會怎樣？", "opts": ["往甲方移動", "往乙方移動", "靜止不動", "先往乙方再回到中線"], "ans": 0, "exp": "甲方拉力 200 公克重比乙方 150 公克重大，兩個力方向相反，迴紋針會往力量大的甲方移動。", "src": "課本 p.95", "fig": {"type": "tug", "left": 200, "right": 150}},
  {"id": "u4-balance-07", "topic": "u4-balance", "type": "single", "diff": 1, "q": "小明和小華用彈簧秤拉迴紋針，拉力如圖。鬆開壓住迴紋針的手後，迴紋針會怎樣？", "opts": ["往小明那邊移動", "往小華那邊移動", "靜止不動", "在兩邊來回移動"], "ans": 2, "exp": "兩邊都用 150 公克重的力往相反方向拉，拉力大小相同、方向相反，迴紋針會靜止不動，達到力的平衡。", "src": "課本 p.95", "fig": {"type": "tug", "left": 150, "right": 150, "labs": ["小明", "小華"]}},
  {"id": "u4-balance-08", "topic": "u4-balance", "type": "tf", "diff": 1, "q": "同一直線上，兩個大小相同、方向相反的拉力拉著迴紋針，迴紋針會靜止不動，這叫做力的平衡。", "ans": 1, "exp": "對。當兩邊拉力大小相同、方向相反時，物體會靜止不動，達到力的平衡。", "src": "課本 p.95"},
  {"id": "u4-balance-09", "topic": "u4-balance", "type": "single", "diff": 2, "q": "做模擬拔河實驗時，要在桌面畫一條中線，並在迴紋針中央做記號、對齊中線。這樣做主要是為了什麼？", "opts": ["看出迴紋針往哪邊移動", "讓迴紋針不容易被拉斷", "量出兩邊拉力相差多少", "讓兩邊的拉力變一樣大"], "ans": 0, "exp": "迴紋針中央的記號先對齊桌面的中線，鬆手後看記號偏向哪一邊，或是仍然對齊中線，就能看出迴紋針往哪邊移動、有沒有移動。拉力的大小要看彈簧秤，中線和記號量不出來。", "src": "課本 p.95"},
  {"id": "u4-balance-10", "topic": "u4-balance", "type": "single", "diff": 2, "q": "做模擬拔河實驗時，要先用手壓住迴紋針，把兩邊拉到要的力量後才鬆手。這樣做的主要原因是什麼？", "opts": ["先把兩邊拉力調好再觀察", "讓迴紋針變得比較重", "讓彈簧秤的指針回到 0", "避免彈簧秤超過彈性限度"], "ans": 0, "exp": "如果不先壓住，迴紋針在拉的過程中就會被拉走。先壓住、把兩邊的拉力調到要的大小（例如 200 和 150 公克重），鬆手後才能觀察迴紋針受到這兩個力會怎麼移動。", "src": "課本 p.95"},
  {"id": "u4-balance-11", "topic": "u4-balance", "type": "single", "diff": 2, "q": "拔河時為什麼不可以突然鬆手？", "opts": ["另一隊可能往後跌倒受傷", "繩子會往鬆手的那隊衝過去", "兩隊的力量會突然變一樣大", "紅布條會從繩子上掉下來"], "ans": 0, "exp": "拔河時兩隊都在用力往後拉，如果一隊突然鬆手，另一隊還在用力往後拉，卻沒有對方的力量拉住，就可能往後跌倒受傷，所以不可以突然鬆手。鬆手後只剩一隊在拉，繩子會往還在拉的那一隊移動。", "src": "課本 p.94"},
  {"id": "u4-balance-12", "topic": "u4-balance", "type": "tf", "diff": 2, "q": "拔河比賽進行時，紅布條一直停著不動，表示兩隊都沒有用力。", "ans": 0, "exp": "錯。兩隊都在用力拉，只是兩隊用的力量一樣大、方向相反，所以紅布條靜止不動。", "src": "課本 p.94–95"},
  {"id": "u4-balance-13", "topic": "u4-balance", "type": "single", "diff": 2, "q": "甲、乙兩方用彈簧秤拉迴紋針，兩邊的拉力如圖，只差 10 公克重。鬆開壓住迴紋針的手後，迴紋針會怎樣？", "opts": ["往乙方移動", "往甲方移動", "靜止不動", "先往甲方再回到中線"], "ans": 0, "exp": "乙方 160 公克重比甲方 150 公克重大，兩個力大小不同、方向相反，迴紋針就會往力量大的乙方移動。只差 10 公克重也不是一樣大，所以不會靜止不動。", "src": "課本 p.95", "fig": {"type": "tug", "left": 150, "right": 160}},
  {"id": "u4-balance-14", "topic": "u4-balance", "type": "single", "diff": 2, "q": "模擬拔河實驗中，鬆手後迴紋針往乙方移動。下列哪一組可能是這次兩邊的拉力？", "opts": ["甲 200、乙 150 公克重", "甲 150、乙 150 公克重", "甲 180、乙 220 公克重", "甲 250、乙 200 公克重"], "ans": 2, "exp": "迴紋針會往拉力大的一方移動，所以乙方的拉力要比甲方大，只有「甲 180、乙 220」符合。甲 150、乙 150 會靜止不動；另外兩組都是甲方比較大，會往甲方移動。", "src": "課本 p.95"},
  {"id": "u4-balance-15", "topic": "u4-balance", "type": "single", "diff": 2, "q": "迴紋針兩端各用一個彈簧秤往相反方向拉，鬆手後迴紋針靜止不動。甲方彈簧秤的讀數是 120 公克重，乙方彈簧秤的讀數應該是多少？", "opts": ["0 公克重", "60 公克重", "120 公克重", "240 公克重"], "ans": 2, "exp": "迴紋針靜止不動，表示兩邊的拉力大小相同、方向相反，所以乙方也是 120 公克重。不是把拉力平分成 60，也不是加起來變成 240；乙方如果沒有出力，迴紋針會往甲方移動。", "src": "課本 p.95"},
  {"id": "u4-balance-16", "topic": "u4-balance", "type": "tf", "diff": 2, "q": "拔河時，紅布條會往人數比較多的那一隊移動。", "ans": 0, "exp": "錯。紅布條會往用力比較大的那一隊移動。人數比較多，用的力量不一定比較大，要看紅布條往哪一隊移動才知道。", "src": "課本 p.94"},
  {"id": "u4-balance-17", "topic": "u4-balance", "type": "single", "diff": 3, "q": "甲、乙兩方用彈簧秤拉迴紋針，拉力如圖。如果想讓鬆手後的迴紋針靜止不動，可以怎麼改？", "opts": ["甲方改用 200 公克重拉", "乙方改用 250 公克重拉", "甲方改用 100 公克重拉", "兩方都再多拉 50 公克重"], "ans": 0, "exp": "要讓迴紋針靜止，兩邊拉力要大小相同、方向相反。甲方改用 200 公克重，兩邊都是 200 公克重，迴紋針就會靜止不動；兩方都多拉 50 公克重，會變成 200 和 250，還是不一樣大。", "src": "課本 p.95", "fig": {"type": "tug", "left": 150, "right": 200}},
  {"id": "u4-balance-18", "topic": "u4-balance", "type": "tf", "diff": 3, "q": "兩個彈簧秤都鉤在迴紋針的同一端，都用 150 公克重往右拉，迴紋針會靜止不動。", "ans": 0, "exp": "錯。力的平衡要兩個力大小相同，而且方向相反。兩個力都往右拉，迴紋針會往右移動，不會靜止不動。", "src": "課本 p.95"},
  {"id": "u4-balance-19", "topic": "u4-balance", "type": "single", "diff": 3, "q": "甲、乙兩隊拔河。剛開始紅布條停在中間不動，過了一會兒，紅布條慢慢往乙隊移動。下列說法何者正確？", "opts": ["一開始兩隊力量一樣，後來乙隊力量比較大", "一開始兩隊都沒用力，後來乙隊才開始用力", "一開始甲隊力量比較大，後來兩隊力量一樣", "從頭到尾都是甲隊用的力量比較大"], "ans": 0, "exp": "紅布條不動時，表示兩隊用的力量一樣大；後來紅布條往乙隊移動，表示乙隊用的力量變得比甲隊大。紅布條不動不是因為兩隊都沒有用力。", "src": "課本 p.94"},
  {"id": "u4-balance-20", "topic": "u4-balance", "type": "single", "diff": 3, "q": "甲、乙兩隊拔河，紅布條先往甲隊移動了一段距離，接著就停在那裡不動。紅布條停住不動的時候，兩隊用的力量是怎樣？", "opts": ["兩隊用的力量一樣大", "甲隊用的力量比較大", "乙隊用的力量比較大", "兩隊都沒有出力"], "ans": 0, "exp": "紅布條停住不動，就表示這時兩隊的力量一樣大、方向相反。它停在靠近甲隊的地方，是之前甲隊力量比較大時被拉過去的，不代表現在甲隊的力量比較大。", "src": "課本 p.94"},
  {"id": "u4-friction-01", "topic": "u4-friction", "type": "single", "diff": 1, "q": "兩個物體互相接觸而且在運動時，會產生一種阻止物體運動的作用力，這種力叫做什麼？", "opts": ["地球引力", "動摩擦力", "磁力", "手的推力"], "ans": 1, "exp": "課本說明：兩個物體相互接觸且運動中，會有一種阻止物體運動的作用力，就是動摩擦力。地球引力（重力）和磁力不必接觸就能產生作用；手的推力是推動物體的力，不是阻止物體運動的力。", "src": "課本 p.96"},
  {"id": "u4-friction-02", "topic": "u4-friction", "type": "tf", "diff": 1, "q": "接觸面愈粗糙，摩擦力愈大，移動物體所需要的力量也愈大。", "ans": 1, "exp": "對。這是課本實驗的假設，實驗結果也支持它：鋪砂紙的粗糙桌面，拉動盒子需要的力比光滑桌面大。", "src": "課本 p.96–97"},
  {"id": "u4-friction-03", "topic": "u4-friction", "type": "tf", "diff": 1, "q": "物體移動時受到的摩擦力，會讓物體移動得更快。", "ans": 0, "exp": "錯。摩擦力會阻擋或減緩物體的移動，讓物體的運動速度變慢，不會讓它變快。", "src": "課本 p.96"},
  {"id": "u4-friction-04", "topic": "u4-friction", "type": "single", "diff": 1, "q": "玩球時，讓球在毛絨絨的墊子上滾動，和在平滑的地板上滾動比較，通常會怎樣？", "opts": ["在墊子上會愈滾愈快", "在墊子上滾得比較快", "兩種地方滾得一樣快", "在墊子上滾得比較慢"], "ans": 3, "exp": "毛絨絨的墊子接觸面比較粗糙，摩擦力比較大，會減緩球的運動，所以球在墊子上通常滾得比較慢。", "src": "課本 p.96"},
  {"id": "u4-friction-05", "topic": "u4-friction", "type": "single", "diff": 2, "q": "用一樣大的力，把同一個盒子分別推出去，讓它在光滑的地板上和粗糙的地毯上滑行。通常在哪一種地面上滑行的距離比較長？", "opts": ["粗糙的地毯，因為摩擦力比較小", "光滑的地板，因為摩擦力比較小", "粗糙的地毯，因為摩擦力比較大", "兩種一樣長，因為推的力一樣大"], "ans": 1, "exp": "光滑的接觸面摩擦力比較小，對盒子運動的阻擋比較少，所以通常滑得比較遠。推的力雖然一樣，但接觸面不同，摩擦力就不同，滑行的距離也不同。", "src": "課本 p.96"},
  {"id": "u4-friction-06", "topic": "u4-friction", "type": "single", "diff": 2, "q": "用力把一個箱子在粗糙的地面上拖行一段距離後，摸摸箱子底部，可能會有什麼感覺？為什麼？", "opts": ["有點冰涼，因為摩擦會把熱帶走", "有點溫熱，因為箱子變得比較重", "有點溫熱，因為摩擦會產生熱能", "沒有變化，因為摩擦力是讓箱子變慢的力"], "ans": 2, "exp": "箱子和地面互相摩擦時，摩擦力會讓阻力增加，也會產生熱能，所以摸起來可能有點溫熱。摩擦力除了會讓箱子變慢，也會產生熱；摩擦不會讓物體變冰涼，也不會讓箱子變重。", "src": "課本 p.96"},
  {"id": "u4-friction-07", "topic": "u4-friction", "type": "tf", "diff": 2, "q": "一樣重的兩個盒子，一個放在光滑的桌面上，一個放在粗糙的桌面上，移動時受到的摩擦力一樣大。", "ans": 0, "exp": "錯。課本實驗的結論是：相同重量的物體，在粗糙和光滑接觸面的摩擦力不同；粗糙的接觸面摩擦力比較大。", "src": "課本 p.97"},
  {"id": "u4-friction-08", "topic": "u4-friction", "type": "single", "diff": 1, "q": "課本的摩擦力實驗中，是用圖中哪一種桌面來模擬「粗糙的接觸面」？", "opts": ["甲", "乙", "丙"], "ans": 2, "exp": "課本的實驗在同一張桌面上，一邊鋪砂紙、一邊不鋪砂紙，用鋪砂紙的那一邊（丙）模擬比較粗糙的接觸面，不鋪的那一邊是比較光滑的接觸面。", "src": "課本 p.97", "fig": {"type": "friction", "rows": [{"lab": "甲", "surf": "towel"}, {"lab": "乙", "surf": "smooth"}, {"lab": "丙", "surf": "sand"}]}},
  {"id": "u4-friction-09", "topic": "u4-friction", "type": "tf", "diff": 1, "q": "做摩擦力實驗時，拉光滑桌面上的盒子和拉鋪砂紙桌面上的盒子，要分別使用兩個不同的彈簧秤。", "ans": 0, "exp": "錯。課本是用同一個彈簧秤鉤住長尾夾來拉兩個盒子，測量的工具相同，結果才能互相比較。", "src": "課本 p.97"},
  {"id": "u4-friction-10", "topic": "u4-friction", "type": "single", "diff": 2, "q": "課本的摩擦力實驗，拉兩個盒子時「刻意改變」的條件是哪一個？", "opts": ["盒子裡砝碼的數量", "用哪一個彈簧秤", "桌面有沒有鋪砂紙", "用哪一張桌子"], "ans": 2, "exp": "實驗在同一張桌子上，一邊鋪砂紙、一邊不鋪，用同一個彈簧秤，盒子都放 6 個砝碼；只有「桌面有沒有鋪砂紙」不一樣，這樣才能知道接觸面對摩擦力的影響。", "src": "課本 p.97"},
  {"id": "u4-friction-11", "topic": "u4-friction", "type": "single", "diff": 1, "q": "做摩擦力實驗時，應該在什麼時候讀出彈簧秤的刻度並記錄下來？", "opts": ["還沒開始拉的時候", "盒子開始移動的時候", "盒子被拉到桌邊停下以後", "手放開彈簧秤以後"], "ans": 1, "exp": "課本的做法是記錄盒子「開始移動時」彈簧秤的刻度，代表拉動盒子需要的力。還沒拉或放手以後，彈簧秤沒有在拉盒子，讀數不能代表拉動盒子的力。", "src": "課本 p.97"},
  {"id": "u4-friction-12", "topic": "u4-friction", "type": "single", "diff": 3, "q": "小明做摩擦力實驗時，光滑桌面上的盒子放 6 個砝碼，鋪砂紙桌面上的盒子只放 2 個砝碼，再比較拉動兩個盒子的讀數。這樣的實驗設計有什麼問題？", "opts": ["沒有問題，兩邊用同一個彈簧秤就公平", "沒有問題，砝碼多少和結果無關", "兩個盒子重量不同，不是只改變接觸面", "鋪砂紙那一盒應該放更多砝碼才對"], "ans": 2, "exp": "課本讓兩個盒子都放 6 個砝碼、重量相同，才能只比較接觸面不同造成的差別。小明的兩個盒子重量不同，就分不清讀數的差別是不是只由接觸面造成的。", "src": "課本 p.97"},
  {"id": "u4-friction-13", "topic": "u4-friction", "type": "single", "diff": 2, "q": "課本的摩擦力實驗中，每一種桌面都要重複拉三次，主要原因是什麼？", "opts": ["拉愈多次，砂紙會變得愈粗糙", "拉三次以後，盒子會變得比較輕", "每次數據可能不同，多測較可靠", "第三次拉的時候讀數才會準"], "ans": 2, "exp": "多次測量時，每次的數據可能有些差異；重複做三次可以互相比對，差異很大的數值可以刪掉或再做一次確認，結果比較可靠。不是哪一次特別準，砂紙和盒子也不會因為多拉幾次而改變。", "src": "課本 p.97"},
  {"id": "u4-friction-14", "topic": "u4-friction", "type": "single", "diff": 3, "q": "小美在光滑桌面上拉同一個盒子三次，記錄盒子開始移動時彈簧秤的讀數，結果如長條圖。下列哪一種處理方式最恰當？", "opts": ["第2次的力最大，只記錄第2次就好", "第2次差很多，可刪掉或再做確認", "把第2次的讀數改成 27 再記錄", "三次都不一樣，實驗全部失敗"], "ans": 1, "exp": "第1、3次是 27 和 26，第2次的 58 和其他兩次差異很大，表示這次測量可能不精確；課本說可以刪掉差異大的數值，或再重複實驗確認。不能自己把數字改掉。", "src": "課本 p.97", "fig": {"type": "chart", "chart": {"type": "bar", "xLabel": "次數", "yLabel": "讀數（公克重）", "x": ["第1次", "第2次", "第3次"], "series": [{"name": "光滑桌面", "data": [27, 58, 26]}]}}},
  {"id": "u4-friction-15", "topic": "u4-friction", "type": "single", "diff": 3, "q": "小華在光滑桌面和鋪砂紙的桌面上，各拉同一個盒子三次，盒子開始移動時的讀數如長條圖。鋪砂紙桌面三次讀數的平均是多少公克重？", "opts": ["27 公克重", "86 公克重", "87 公克重", "89 公克重"], "ans": 2, "exp": "鋪砂紙的三次讀數是 86、89、86，加起來 261，除以 3 等於 87 公克重。86 和 89 只是其中一次的讀數，27 則是光滑桌面三次的平均。", "src": "課本 p.97", "fig": {"type": "chart", "chart": {"type": "bar", "xLabel": "次數", "yLabel": "讀數（公克重）", "x": ["第1次", "第2次", "第3次"], "series": [{"name": "光滑桌面", "data": [26, 28, 27]}, {"name": "鋪砂紙", "data": [86, 89, 86]}], "labels": true}}},
  {"id": "u4-friction-16", "topic": "u4-friction", "type": "single", "diff": 2, "q": "用同一個彈簧秤，分別拉動圖中兩個一樣重的盒子。哪一個盒子開始移動時需要比較大的力？理由是什麼？", "opts": ["甲，粗糙的接觸面摩擦力比較大", "乙，光滑的接觸面摩擦力比較大", "甲，砂紙會讓盒子變得比較重", "兩個一樣大，因為盒子一樣重"], "ans": 0, "exp": "甲的桌面鋪了砂紙，接觸面比較粗糙，摩擦力比較大，所以拉動需要比較大的力。砂紙不會讓盒子變重；盒子一樣重，但接觸面不同，摩擦力也不同。", "src": "課本 p.96–97", "fig": {"type": "friction", "rows": [{"lab": "甲", "surf": "sand"}, {"lab": "乙", "surf": "smooth"}]}},
  {"id": "u4-friction-17", "topic": "u4-friction", "type": "single", "diff": 2, "q": "小英用同一個彈簧秤，在三種桌面上拉一樣重的盒子，圖中是盒子開始移動時的讀數。依照讀數，三種接觸面的摩擦力由小到大排列，下列哪一個正確？", "opts": ["甲＜丙＜乙", "甲＜乙＜丙", "乙＜丙＜甲", "丙＜甲＜乙"], "ans": 0, "exp": "盒子開始移動時彈簧秤的讀數愈大，表示拉動需要的力愈大、摩擦力也愈大。讀數是甲 27、丙 52、乙 87 公克重，所以摩擦力由小到大是甲＜丙＜乙；鋪毛巾的丙比光滑桌面粗糙，但比砂紙光滑。", "src": "課本 p.97", "fig": {"type": "friction", "rows": [{"lab": "甲", "surf": "smooth", "g": 27}, {"lab": "乙", "surf": "sand", "g": 87}, {"lab": "丙", "surf": "towel", "g": 52}]}},
  {"id": "u4-friction-18", "topic": "u4-friction", "type": "tf", "diff": 3, "q": "圖中甲是光滑桌面，盒子開始移動時彈簧秤的讀數是 27 公克重。這表示光滑的接觸面摩擦力比較小，但不是沒有摩擦力。", "ans": 1, "exp": "對。接觸面愈光滑，摩擦力愈小，但仍然要用 27 公克重的力才拉得動盒子，表示還是有摩擦力；鋪砂紙的乙要 87 公克重，摩擦力比較大。", "src": "課本 p.97", "fig": {"type": "friction", "rows": [{"lab": "甲", "surf": "smooth", "g": 27}, {"lab": "乙", "surf": "sand", "g": 87}]}},
  {"id": "u4-friction-19", "topic": "u4-friction", "type": "single", "diff": 1, "q": "下列哪一種設計，是為了「增加」摩擦力？", "opts": ["門軸塗上潤滑油", "直排輪的光滑輪子", "鞋子底部的紋路", "滑水道上有水流下"], "ans": 2, "exp": "接觸面有紋路或表面粗糙，可以增加摩擦力，鞋底的紋路讓人走路不容易滑倒。塗油、光滑的輪子、滑水道上的水，都是減少摩擦力的設計。", "src": "課本 p.98"},
  {"id": "u4-friction-20", "topic": "u4-friction", "type": "tf", "diff": 1, "q": "在門軸塗上潤滑油，可以增加門軸的摩擦力。", "ans": 0, "exp": "錯。在接觸面塗油可以「減少」摩擦力，門開關起來比較省力、順暢。", "src": "課本 p.98"},
  {"id": "u4-friction-21", "topic": "u4-friction", "type": "tf", "diff": 2, "q": "瓶蓋上的紋路可以增加摩擦力，轉開瓶蓋時雖然比較費力，但手比較不容易打滑，使用上比較方便。", "ans": 1, "exp": "對。課本說：有些物體增加摩擦力後，使用時雖然費力，但是能增加使用的便利性，例如開塑膠瓶蓋。", "src": "課本 p.98"},
  {"id": "u4-friction-22", "topic": "u4-friction", "type": "single", "diff": 1, "q": "照片中的購物車底下裝了輪子。這樣的設計會讓摩擦力怎樣改變？推起來感覺如何？", "opts": ["摩擦力增加，推起來比較省力", "摩擦力減少，推起來比較省力", "摩擦力增加，推起來比較費力", "摩擦力減少，推起來比較費力"], "ans": 1, "exp": "在接觸面裝滾輪可以減少摩擦力；減少摩擦力後，使用時比較省力，例如推動購物車。", "src": "課本 p.98", "img": "u4/cart-wheel"},
  {"id": "u4-friction-23", "topic": "u4-friction", "type": "single", "diff": 2, "q": "照片中的購物車裝上輪子。下列哪一種設計的目的，和購物車裝輪子相同？", "opts": ["鞋子底部有紋路", "寶特瓶瓶蓋上有條紋", "腳踏車的鏈條加潤滑油", "雪地行車時輪胎加鐵鍊"], "ans": 2, "exp": "購物車裝輪子和鏈條加潤滑油，都是為了減少摩擦力、使用時比較省力。鞋底紋路、瓶蓋條紋、輪胎加鐵鍊則是為了增加摩擦力。", "src": "課本 p.98", "img": "u4/cart-wheel"},
  {"id": "u4-friction-24", "topic": "u4-friction", "type": "single", "diff": 2, "q": "車輛在下雪的路面行駛時，輪胎常會加上鐵鍊，主要的目的是什麼？", "opts": ["減少摩擦力，讓車子跑得更快", "減少摩擦力，讓輪胎比較省力", "讓輪胎變重，就不需要摩擦力", "增加摩擦力，比較不容易打滑"], "ans": 3, "exp": "雪地很滑，摩擦力小；輪胎加上鐵鍊可以增加摩擦力，車子比較不容易打滑。這是增加摩擦力的例子，不是為了省力或跑得更快。", "src": "課本 p.98"},
  {"id": "u4-friction-25", "topic": "u4-friction", "type": "tf", "diff": 1, "q": "滑水道上有水流下，可以減少摩擦力，幫助人滑得比較順。", "ans": 1, "exp": "對。滑水道上的水可以減少人和滑道之間的摩擦力，協助滑行，這是減少摩擦力的例子。", "src": "課本 p.98"},
  {"id": "u4-friction-26", "topic": "u4-friction", "type": "single", "diff": 2, "q": "小華想讓一個很重的櫃子比較容易推動，下列哪一個方法最合適？", "opts": ["在櫃子底下黏上砂紙", "在地板上鋪止滑墊", "在櫃子裡多放一些書", "在櫃子底下裝上輪子"], "ans": 3, "exp": "裝上輪子可以減少摩擦力，推起來比較省力。砂紙和止滑墊會增加摩擦力，多放書會讓櫃子更重，都不會比較好推。", "src": "課本 p.98"},
  {"id": "u4-friction-27", "topic": "u4-friction", "type": "single", "diff": 3, "q": "下雨天走廊很容易滑倒。小安想選一種地墊鋪在走廊上，她用同一個彈簧秤，在甲、乙、丙三種地墊上拉同一個裝了 6 個砝碼的盒子，盒子開始移動時讀數的平均是：甲 45、乙 90、丙 30 公克重。鋪哪一種地墊，走路可能最不容易滑倒？為什麼？", "opts": ["乙，盒子最難拉動，摩擦力最大", "乙，讀數最大，表示地墊最光滑", "丙，盒子最容易拉動，摩擦力最大", "丙，摩擦力最小，走起來最省力"], "ans": 0, "exp": "盒子開始移動時讀數愈大，表示拉動需要的力愈大，接觸面的摩擦力也愈大。乙的 90 公克重最大，摩擦力最大，鞋子比較不容易打滑；丙的讀數最小、摩擦力最小，走在上面反而比較容易滑倒。", "src": "課本 p.97–98"},
  {"id": "u4-friction-28", "topic": "u4-friction", "type": "single", "diff": 3, "q": "小明說：「摩擦力會阻礙物體運動，所以生活中的摩擦力都是愈小愈好。」下列哪一個例子最能說明他的想法不正確？", "opts": ["推車裝上輪子，推起來比較省力", "鞋底有紋路，走路比較不會滑倒", "鏈條加潤滑油，踩起來比較順", "滑水道上有水，滑起來比較順"], "ans": 1, "exp": "鞋底的紋路是增加摩擦力的設計，讓走路不容易滑倒，說明有時候需要比較大的摩擦力。其他三個都是減少摩擦力的好處，不能說明小明的想法不對。", "src": "課本 p.98"},
  {"id": "u4-speed-01", "topic": "u4-speed", "type": "single", "diff": 1, "q": "「速度」是用來描述物體的什麼？", "opts": ["移動的快慢", "重量的大小", "受力的方向", "形狀的改變"], "ans": 0, "exp": "課本說「速度」是用來描述物體移動快慢的方式。重量、受力方向、形狀改變都不是速度在描述的事。", "src": "課本 p.100"},
  {"id": "u4-speed-02", "topic": "u4-speed", "type": "single", "diff": 1, "q": "下列哪一個是速度、距離和時間的正確關係？", "opts": ["速度＝距離÷時間", "速度＝時間÷距離", "速度＝距離×時間", "速度＝距離＋時間"], "ans": 0, "exp": "速度＝距離÷時間。用移動的距離除以花費的時間，就知道每秒（或每小時）移動多遠；單位相同時，數字愈大表示移動得愈快。", "src": "課本 p.100"},
  {"id": "u4-speed-03", "topic": "u4-speed", "type": "tf", "diff": 1, "q": "跑相同的距離時，花費的時間愈少，表示跑得愈快。", "ans": 1, "exp": "對。距離相同時，比較花費的時間：時間愈少（愈短）跑得愈快，時間愈多跑得愈慢。", "src": "課本 p.100、108"},
  {"id": "u4-speed-04", "topic": "u4-speed", "type": "tf", "diff": 1, "q": "在相同的時間內，移動的距離愈短，表示跑得愈快。", "ans": 0, "exp": "錯。相同時間內，移動的距離愈長（愈遠）才表示跑得愈快；距離愈短表示跑得愈慢。", "src": "課本 p.100、108"},
  {"id": "u4-speed-05", "topic": "u4-speed", "type": "tf", "diff": 1, "q": "移動的距離和移動的時間長短，都會影響移動速度的快慢。", "ans": 1, "exp": "對。速度＝距離÷時間，距離和時間兩個因素都會影響速度；所以兩個人的距離和時間都不同時，不能只看其中一個數字比快慢。", "src": "課本 p.100"},
  {"id": "u4-speed-06", "topic": "u4-speed", "type": "single", "diff": 1, "q": "照片是田徑 100 公尺賽跑的起跑。這種比賽是用哪一種方式比較誰跑得快？", "opts": ["距離相同，比較花的時間", "時間相同，比較跑的距離", "比較誰起跑時身體壓得最低", "比較誰每一步跨得比較大"], "ans": 0, "exp": "100 公尺賽跑是每個人都跑固定的距離，比較跑完需要多少時間，花的時間愈短跑得愈快。「時間相同，比較距離」是下課常玩的另一種比法。", "src": "課本 p.99", "img": "u4/sprint", "cap": "田徑賽跑的起跑"},
  {"id": "u4-speed-07", "topic": "u4-speed", "type": "tf", "diff": 2, "q": "只知道小美跑了 400 公尺、小真跑了 300 公尺，就可以判斷小美跑得比較快。", "ans": 0, "exp": "錯。不知道兩人各花了多少時間，只看距離不能比快慢；要時間相同才能直接比距離，或是用距離÷時間算出速度再比較。", "src": "課本 p.100"},
  {"id": "u4-speed-08", "topic": "u4-speed", "type": "single", "diff": 2, "q": "下列哪一種比賽，是用「相同時間，比較移動的距離」來比快慢？", "opts": ["1 分鐘內繞操場跑，比誰跑的圈數多", "100 公尺賽跑比誰先跑到終點", "50 公尺游泳比誰用的時間最少", "200 公尺接力比哪一隊先跑完"], "ans": 0, "exp": "1 分鐘內每個人跑的時間相同，繞操場跑的圈數愈多代表距離愈長、跑得愈快。另外三種比賽都是距離固定，比較花費的時間。", "src": "課本 p.99"},
  {"id": "u4-speed-09", "topic": "u4-speed", "type": "single", "diff": 2, "q": "小依這一組比賽「誰在 30 秒內跑得最遠」。為什麼每個人都要跑一樣的 30 秒？", "opts": ["時間相同才能直接比距離", "這樣每個人跑的距離才會一樣長", "跑超過 30 秒就沒有辦法量距離", "這樣就不必記錄每個人跑了多遠"], "ans": 0, "exp": "要用距離比快慢，時間必須相同；如果有人跑 30 秒、有人跑 40 秒，跑得遠可能只是因為跑得久。每個人都跑 30 秒再比距離，距離愈長愈快。", "src": "課本 p.99–100"},
  {"id": "u4-speed-10", "topic": "u4-speed", "type": "tf", "diff": 2, "q": "比較兩個人跑步的快慢時，時間和距離兩個都要固定，才能比較。", "ans": 0, "exp": "錯。只要固定其中一個就能比較：距離固定，比花費的時間；時間固定，比移動的距離。兩個都不同時，也可以用「距離÷時間」算出速度來比較。", "src": "課本 p.99–100"},
  {"id": "u4-speed-11", "topic": "u4-speed", "type": "single", "diff": 2, "q": "高速公路的「區間測速」是量車子通過同一段固定距離所花的時間。三輛車通過同一段測速區間，公車用 4 分鐘、轎車用 3 分鐘、貨車用 5 分鐘。哪一輛車的車速最快？", "opts": ["轎車", "公車", "貨車", "三輛一樣快"], "ans": 0, "exp": "距離相同時，花費的時間愈短，速度愈快。轎車只用 3 分鐘，時間最短，所以車速最快；貨車用 5 分鐘，是三輛中最慢的。", "src": "課本 p.100"},
  {"id": "u4-speed-12", "topic": "u4-speed", "type": "single", "diff": 1, "q": "長條圖是三位同學各跑 30 秒的距離。誰跑得最快？", "opts": ["小依", "小洲", "小凰"], "ans": 0, "exp": "時間都是 30 秒，跑的距離愈長愈快。小依跑 200 公尺，長條最高，所以跑得最快；小凰 150 公尺最短，跑得最慢。", "src": "課本 p.100–101", "fig": {"type": "chart", "chart": {"type": "bar", "x": ["小凰", "小依", "小洲"], "series": [{"name": "30 秒跑的距離", "data": [150, 200, 180]}], "xLabel": "名字", "yLabel": "距離（公尺）"}}},
  {"id": "u4-speed-13", "topic": "u4-speed", "type": "single", "diff": 2, "q": "小依這一組固定跑 30 秒、小南這一組固定跑 100 公尺。兩組要比較組員跑步的快慢，分別要比較什麼？", "opts": ["小依組比距離，小南組比時間", "小依組比時間，小南組比距離", "兩組都比較跑的時間", "兩組都比較跑的距離"], "ans": 0, "exp": "小依這一組時間固定，要比較跑的距離，距離愈長愈快；小南這一組距離固定，要比較花費的時間，時間愈短愈快。", "src": "課本 p.100"},
  {"id": "u4-speed-14", "topic": "u4-speed", "type": "tf", "diff": 2, "q": "長條圖是小南這一組跑 100 公尺所花的時間。圖中長條最高的人跑得最快。", "ans": 0, "exp": "錯。這張圖的長條表示花費的時間，長條最高的小方用了 22 秒最多，跑得最慢；長條最短的小美用 18 秒，跑得最快。", "src": "課本 p.100–101", "fig": {"type": "chart", "chart": {"type": "bar", "x": ["小南", "小美", "小方"], "series": [{"name": "跑 100 公尺的時間", "data": [20, 18, 22]}], "xLabel": "名字", "yLabel": "時間（秒）"}}},
  {"id": "u4-speed-15", "topic": "u4-speed", "type": "single", "diff": 1, "q": "把跑步的數據紀錄表轉換成長條圖，主要的好處是什麼？", "opts": ["更容易比較出誰快誰慢", "可以讓每個人跑得更快", "畫圖時可以不必寫單位", "每個人的成績會變得一樣"], "ans": 0, "exp": "課本說把紀錄表的數據轉換成長條圖，可以更容易比較。長條圖仍然要標示橫軸、縱軸代表什麼和單位，數據本身也不會改變。", "src": "課本 p.101"},
  {"id": "u4-speed-16", "topic": "u4-speed", "type": "single", "diff": 2, "q": "小依這一組（時間固定 30 秒）要把跑步紀錄表畫成長條圖。表示每個人成績的那一軸，應該用什麼單位？", "opts": ["公尺", "秒", "公里／小時", "公克重"], "ans": 0, "exp": "這一組每個人都跑 30 秒，比的是跑了多遠，所以成績那一軸要用距離的單位「公尺」。小南這一組距離固定 100 公尺，比的是時間，才用「秒」。", "src": "課本 p.101"},
  {"id": "u4-speed-17", "topic": "u4-speed", "type": "single", "diff": 2, "q": "長條圖是小安這一組每個人跑 50 公尺所花的時間。誰跑得最慢？", "opts": ["小平", "小真", "小樂", "小安"], "ans": 0, "exp": "距離都是 50 公尺，花的時間愈多跑得愈慢。小平用 11 秒，長條最高，是最慢的；長條最短的小真用 8 秒，才是最快的。", "src": "課本 p.100–101", "fig": {"type": "chart", "chart": {"type": "bar", "x": ["小安", "小平", "小真", "小樂"], "series": [{"name": "跑 50 公尺的時間", "data": [9, 11, 8, 10]}], "xLabel": "名字", "yLabel": "時間（秒）", "yMax": 15}}},
  {"id": "u4-speed-18", "topic": "u4-speed", "type": "single", "diff": 2, "q": "長條圖是四輛玩具車都跑 5 秒鐘所移動的距離。哪一輛車跑得最慢？", "opts": ["丙車", "乙車", "甲車", "丁車"], "ans": 0, "exp": "時間都是 5 秒，移動的距離愈短跑得愈慢。丙車只移動 90 公分，長條最短，跑得最慢；乙車移動 150 公分，跑得最快。", "src": "課本 p.100–101", "fig": {"type": "chart", "chart": {"type": "bar", "x": ["甲車", "乙車", "丙車", "丁車"], "series": [{"name": "5 秒移動的距離", "data": [120, 150, 90, 135]}], "xLabel": "玩具車", "yLabel": "距離（公分）"}}},
  {"id": "u4-speed-19", "topic": "u4-speed", "type": "single", "diff": 3, "q": "小庭把三個人的跑步紀錄畫成這張長條圖，但忘了標示縱軸的名稱和單位。只看這張圖，可以判斷誰跑得最快嗎？", "opts": ["不能，長條可能是距離或時間", "可以，長條最高的小宇最快", "可以，長條最短的小庭最快", "可以，長條在中間的小凱最快"], "ans": 0, "exp": "如果長條是相同時間內跑的距離，長條最高的小宇最快；如果是跑相同距離花的時間，長條最短的小庭才最快。不知道長條代表什麼就無法判斷，所以長條圖一定要標示代表什麼和單位。", "src": "課本 p.101", "fig": {"type": "chart", "chart": {"type": "bar", "x": ["小凱", "小庭", "小宇"], "series": [{"name": "成績", "data": [16, 14, 18]}]}}},
  {"id": "u4-speed-20", "topic": "u4-speed", "type": "tf", "diff": 1, "q": "「公里／小時」表示每小時移動幾公里，也稱為「時速」。", "ans": 1, "exp": "對。課本的動物速度資料用「公里／小時」當單位，表示每小時跑幾公里，也就是時速。", "src": "課本 p.103"},
  {"id": "u4-speed-21", "topic": "u4-speed", "type": "tf", "diff": 1, "q": "高速火車的時速是 300 公里。課本的動物速度資料中，只有遊隼的時速比高速火車快。", "ans": 1, "exp": "對。遊隼的時速 322 公里，超過高速火車的 300 公里；第二快的印度豹時速 113 公里，比高速火車慢很多。", "src": "課本 p.103"},
  {"id": "u4-speed-22", "topic": "u4-speed", "type": "single", "diff": 1, "q": "課本的動物速度資料中，哪一種動物的時速比短跑選手博爾特（時速 39 公里）慢？", "opts": ["蝸牛", "犀牛", "鴕鳥", "羚羊"], "ans": 0, "exp": "蝸牛的時速只有 0.011 公里，比博爾特慢很多；犀牛（56 公里）、鴕鳥（72 公里）、羚羊（98 公里）的時速都比博爾特快。在這份資料中，博爾特只比蝸牛快。", "src": "課本 p.102–103"},
  {"id": "u4-speed-23", "topic": "u4-speed", "type": "single", "diff": 2, "q": "課本的「各種動物運動速度比較」資料，是用什麼方式比較動物的快慢？", "opts": ["比較每小時能移動幾公里", "比較跑完 100 公尺花幾秒", "比較身體體型的大小", "比較每天活動多少小時"], "ans": 0, "exp": "資料用「時速（公里／小時）」，也就是每小時能移動幾公里來比較；大家用同樣的單位，數字愈大就愈快。資料裡沒有每種動物跑 100 公尺的秒數。", "src": "課本 p.102–103"},
  {"id": "u4-speed-24", "topic": "u4-speed", "type": "single", "diff": 2, "q": "一輛汽車 3 小時行駛了 180 公里。如果一路上的速度都相同，這輛汽車的時速是多少？", "opts": ["時速 60 公里", "時速 540 公里", "時速 180 公里", "時速 90 公里"], "ans": 0, "exp": "時速是每小時移動幾公里：180÷3＝60，所以是時速 60 公里。180 公里是 3 小時的總距離，不是每小時的距離；540 是把距離和時間相乘，算法錯了。", "src": "課本 p.100、103"},
  {"id": "u4-speed-25", "topic": "u4-speed", "type": "single", "diff": 3, "q": "長條圖是短跑選手博爾特和三種動物的時速。哪一種動物的時速超過博爾特時速的 2 倍？", "opts": ["羚羊", "鴕鳥", "犀牛"], "ans": 0, "exp": "博爾特時速 39 公里，2 倍是 39×2＝78 公里。只有羚羊的 98 公里超過 78 公里；鴕鳥 72 公里雖然很快，但還不到 78 公里。", "src": "課本 p.102–103", "fig": {"type": "chart", "chart": {"type": "bar", "x": ["博爾特", "犀牛", "鴕鳥", "羚羊"], "series": [{"name": "時速", "data": [39, 56, 72, 98]}], "yLabel": "時速（公里／小時）"}}},
  {"id": "u4-speed-26", "topic": "u4-speed", "type": "single", "diff": 3, "q": "高速火車的時速是 300 公里。如果它一直用這個速度行駛 30 分鐘（半小時），可以行駛幾公里？", "opts": ["150 公里", "300 公里", "600 公里", "9000 公里"], "ans": 0, "exp": "時速 300 公里表示 1 小時行駛 300 公里；30 分鐘是半小時，所以行駛 300÷2＝150 公里。300 公里是行駛 1 小時的距離；9000 是把 300 和 30 相乘，把分鐘當成小時算了。", "src": "課本 p.103"},
  {"id": "u4-speed-27", "topic": "u4-speed", "type": "single", "diff": 2, "q": "小明 10 秒鐘跑了 50 公尺。他平均每秒跑幾公尺？", "opts": ["5 公尺", "500 公尺", "40 公尺", "60 公尺"], "ans": 0, "exp": "速度＝距離÷時間：50÷10＝5，平均每秒跑 5 公尺。500 是把距離和時間相乘；40、60 是相減、相加，都不是速度的算法。", "src": "課本 p.100"},
  {"id": "u4-speed-28", "topic": "u4-speed", "type": "single", "diff": 3, "q": "小光用 20 秒跑了 100 公尺；小亮用 30 秒跑了 180 公尺。誰跑得比較快？", "opts": ["小亮", "小光", "兩人一樣快", "距離不同，無法比較"], "ans": 0, "exp": "距離和時間都不同時，用速度＝距離÷時間比較：小光 100÷20＝5，每秒 5 公尺；小亮 180÷30＝6，每秒 6 公尺，所以小亮比較快。只因為小光用的時間比較短就說他比較快，是錯的。", "src": "課本 p.100"},
  {"id": "u4-speed-29", "topic": "u4-speed", "type": "tf", "diff": 3, "q": "阿凱用 16 秒跑了 80 公尺，阿哲用 20 秒跑了 100 公尺。因為阿凱用的時間比較少，所以阿凱跑得比較快。", "ans": 0, "exp": "錯。兩人跑的距離不同，不能只比時間。算速度：阿凱 80÷16＝5、阿哲 100÷20＝5，兩人每秒都跑 5 公尺，一樣快。", "src": "課本 p.100"},
  {"id": "u4-speed-30", "topic": "u4-speed", "type": "single", "diff": 3, "q": "小依 30 秒跑了 200 公尺；小南跑 100 公尺用了 20 秒。如果小南一直用相同的速度跑 30 秒，可以跑幾公尺？誰跑得比較快？", "opts": ["150 公尺，小依比較快", "150 公尺，小南比較快", "300 公尺，小南比較快", "兩人比的方式不同，所以無法比較"], "ans": 0, "exp": "小南每秒跑 100÷20＝5 公尺，30 秒可以跑 5×30＝150 公尺，比小依的 200 公尺短，所以小依比較快。時間和距離都不同時，可以先換成相同的時間再比距離。", "src": "課本 p.100"},
  {"id": "u4-energy-01", "topic": "u4-energy", "type": "single", "diff": 1, "q": "溜滑梯時，我們不斷出力往上爬到比較高的地方，能量就轉化到比較高的位置。課本把這種能量簡稱為什麼？", "opts": ["動能", "位能", "熱能", "光能"], "ans": 1, "exp": "往上爬到比較高的地方，能量轉化到較高的位置，簡稱「位能」。動能和物體運動的快慢有關，往下溜、速度變快時，動能才會變大。", "src": "課本 p.104"},
  {"id": "u4-energy-02", "topic": "u4-energy", "type": "single", "diff": 1, "q": "圖中是同一個人從滑梯上滑下來的三個位置。這個人在哪一個位置時，具有的位能最多？", "opts": ["甲", "乙", "丙"], "ans": 2, "exp": "位置愈高，位能愈多。丙在滑梯的最高處，所以位能最多；往下滑的過程中，位能會漸漸轉換成動能。", "src": "課本 p.104", "fig": {"type": "slide", "lab": ["丙", "甲", "乙"]}},
  {"id": "u4-energy-03", "topic": "u4-energy", "type": "tf", "diff": 1, "q": "從滑梯上往下溜時，速度愈來愈快，表示具有的動能愈來愈大。", "ans": 1, "exp": "對。動能是物體運動所具有的能量，速度愈快，動能愈大；往下溜時速度變快，表示動能變大。", "src": "課本 p.104"},
  {"id": "u4-energy-04", "topic": "u4-energy", "type": "single", "diff": 2, "q": "從滑梯的高處往下溜，速度愈來愈快。如果不考慮摩擦力，這個過程是哪一種能量轉換？", "opts": ["位能轉換成動能", "動能轉換成位能", "熱能轉換成動能", "電能轉換成位能"], "ans": 0, "exp": "往下溜時位置變低、速度變快，位能減少、動能增加，所以是位能轉換成動能。往上爬到高處時，才是讓位能變多。", "src": "課本 p.104"},
  {"id": "u4-energy-05", "topic": "u4-energy", "type": "single", "diff": 2, "q": "如果考慮摩擦力，從滑梯溜下來的過程中，位能會轉化為哪些能量？", "opts": ["只有動能", "動能和熱能", "熱能和光能", "動能和電能"], "ans": 1, "exp": "溜下來時身體和滑梯會互相摩擦，摩擦會產生熱，所以位能會轉化為動能和熱能。不考慮摩擦力時，位能才是只轉化為動能。", "src": "課本 p.104"},
  {"id": "u4-energy-06", "topic": "u4-energy", "type": "tf", "diff": 2, "q": "溜滑梯時有摩擦力，有一部分能量變成了熱，所以整個過程的總能量變少了。", "ans": 0, "exp": "錯。考慮摩擦力時，位能會轉化為動能和熱能，熱能並沒有消失，總能量都維持不變。", "src": "課本 p.104"},
  {"id": "u4-energy-07", "topic": "u4-energy", "type": "tf", "diff": 2, "q": "小美坐在滑梯的最高處，還沒有往下溜。因為她沒有在運動，所以她沒有任何能量。", "ans": 0, "exp": "錯。小美雖然還沒有在運動，但她在高處，具有位能；往下溜時，位能就會轉換成動能。", "src": "課本 p.104"},
  {"id": "u4-energy-08", "topic": "u4-energy", "type": "single", "diff": 3, "q": "小明和小華在同一座溜滑梯玩。小明從最高處開始溜，小華從滑梯中間開始溜。滑到最下面時，通常誰的速度比較快？", "opts": ["小明，因為出發的位置比較高、位能比較多", "小華，因為溜的距離比較短", "兩人一樣快，因為是同一座滑梯", "小華，因為在中間出發時，他已經具有比較多的動能"], "ans": 0, "exp": "從愈高的地方出發，位能愈多，往下溜時轉換成的動能也愈多，所以小明滑到下面時通常比較快。小華在中間出發時是靜止的，並沒有比較多的動能。", "src": "課本 p.104"},
  {"id": "u4-energy-09", "topic": "u4-energy", "type": "single", "diff": 2, "q": "圖中是盪秋千時同一次擺盪的三個位置。秋千在哪一個位置時速度最快、動能最多？", "opts": ["甲", "乙", "丙"], "ans": 0, "exp": "盪到比較低的地方時速度會變快，具有比較多的動能；甲是最低點，所以速度最快。乙和丙在兩邊比較高的地方，位能比較多。", "src": "課本 p.104", "fig": {"type": "swing", "lab": ["乙", "甲", "丙"]}},
  {"id": "u4-energy-10", "topic": "u4-energy", "type": "tf", "diff": 3, "q": "看圖判斷：秋千從乙盪到甲的過程中，速度會愈來愈慢，位能會愈來愈多。", "ans": 1, "exp": "對。乙是最低點、甲是右邊最高點；秋千往高處盪時愈來愈慢，動能減少、位能增加。盪回低處時，位能又會轉換成動能，能量可以轉換成不同的方式存在。", "src": "課本 p.104", "fig": {"type": "swing", "lab": ["丙", "乙", "甲"]}},
  {"id": "u4-energy-11", "topic": "u4-energy", "type": "single", "diff": 2, "q": "蘋果從樹上掉下來，愈往下掉速度愈快。在掉落的過程中，蘋果的能量怎麼變化？", "opts": ["位能變少，動能變多", "位能變多，動能變少", "位能和動能都變多", "位能和動能都不變"], "ans": 0, "exp": "蘋果愈往下，位置愈低，位能愈少；速度愈來愈快，動能愈多。這和從滑梯往下溜一樣，是位能轉換成動能。", "src": "課本 p.104"},
  {"id": "u4-energy-12", "topic": "u4-energy", "type": "tf", "diff": 1, "q": "盪秋千時，盪到比較高的地方，就具有比較多的動能。", "ans": 0, "exp": "錯。盪到比較高的地方時，具有比較多的「位能」；盪到比較低的地方時速度變快，才具有比較多的動能。", "src": "課本 p.104"},
  {"id": "u4-energy-13", "topic": "u4-energy", "type": "single", "diff": 1, "q": "照片中的手電筒運作時，主要的能量轉換是哪一種？", "opts": ["電轉換成光", "光轉換成電", "電轉換成轉動", "摩擦轉換成熱"], "ans": 0, "exp": "手電筒靠電池的電運作，把電轉換成光。光轉換成電是太陽能板，電轉換成轉動是電風扇，摩擦轉換成熱是搓手取暖。", "src": "課本 p.105", "img": "u4/flashlight", "cap": "手電筒"},
  {"id": "u4-energy-14", "topic": "u4-energy", "type": "single", "diff": 1, "q": "照片中的太陽能板，主要的能量轉換是哪一種？", "opts": ["光轉換成電", "電轉換成光", "電轉換成轉動", "摩擦轉換成熱"], "ans": 0, "exp": "太陽能板可以把太陽光轉換成電。電轉換成光是手電筒，電轉換成轉動是電風扇，摩擦轉換成熱是搓手取暖。", "src": "課本 p.105", "img": "u4/solar-panel", "cap": "太陽能板"},
  {"id": "u4-energy-15", "topic": "u4-energy", "type": "single", "diff": 1, "q": "天氣冷的時候，雙手互相摩擦，手會漸漸變得暖和。這主要是摩擦產生了哪一種能量？", "opts": ["光能", "電能", "熱能", "位能"], "ans": 2, "exp": "雙手互相摩擦時會產生熱，所以手會變暖和，這是摩擦轉換成熱的例子。", "src": "課本 p.105"},
  {"id": "u4-energy-16", "topic": "u4-energy", "type": "single", "diff": 2, "q": "盪秋千時，如果有人在後面順著擺盪的方向不斷推秋千，和沒有人推比較，秋千擺到最下方時通常會怎樣？", "opts": ["速度比較快，動能比較大", "速度比較慢，動能比較小", "速度比較快，位能比較大", "速度不變，因為擺到的位置一樣低"], "ans": 0, "exp": "不斷對秋千施加外力，會使秋千擺到下方時速度加快，動能也變大。秋千擺到最下方的高度沒有改變，所以位能並沒有比較大。", "src": "課本 p.104"},
  {"id": "u4-energy-17", "topic": "u4-energy", "type": "tf", "diff": 2, "q": "照片中的電風扇開了一段時間後會有發熱的情形，這表示電風扇運作時，有一部分能量轉換成了熱能。", "ans": 1, "exp": "對。電風扇主要是把電能轉換成讓葉片轉動的能量，但過程中無法避免發熱，有一部分能量被轉換成熱能。", "src": "課本 p.105", "img": "u4/fan", "cap": "電風扇"},
  {"id": "u4-energy-18", "topic": "u4-energy", "type": "single", "diff": 3, "q": "有一臺小電風扇直接接在太陽能板上，太陽光照到太陽能板時，電風扇的葉片就會轉動。這個過程中，主要的能量轉換順序是哪一個？", "opts": ["光→電→轉動", "電→光→轉動", "轉動→電→光", "光→熱→轉動"], "ans": 0, "exp": "太陽能板先把太陽光轉換成電，電再讓電風扇的葉片轉動，所以是光→電→轉動。太陽能板是把光轉換成電，不是轉換成熱。", "src": "課本 p.105"},
  {"id": "u4-energy-19", "topic": "u4-energy", "type": "single", "diff": 1, "q": "不論能量怎樣轉換形式，總能量都保持不變。這種總能量不變的狀態，稱為什麼？", "opts": ["能量守恆", "能量損耗", "能量轉換", "力的平衡"], "ans": 0, "exp": "總能量不變的狀態稱為「能量守恆」。能量轉換是能量改變形式的過程；能量損耗是指可以使用的能量變少；力的平衡是兩個大小相同、方向相反的力讓物體靜止不動。", "src": "課本 p.105"},
  {"id": "u4-energy-20", "topic": "u4-energy", "type": "single", "diff": 3, "q": "自然界中的能量可以不斷轉換形態。能量轉換很多次以後，「可以使用的能量」通常會變少，原因是什麼？", "opts": ["轉換時會有一部分變成熱，不能再拿來用", "轉換時會有一部分能量消失不見", "能量只能轉換一次，之後就不能再用", "總能量會隨著轉換次數愈來愈少"], "ans": 0, "exp": "能量轉換時，無法避免有一部分變成熱，例如電風扇會發熱，這些熱不能再拿來讓葉片轉動，所以可以使用的能量被損耗。但這些能量並沒有消失，總能量還是不變，這就是能量守恆。", "src": "課本 p.105"}
]);
